quests[55590] = { id = 55590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fassung bewahren", description = "<Samuel wird sicherlich sehr daran interessiert sein, von Eurer Untersuchung dieses Schreins zu erfahren.\n\nGanz besonders den Teil, als Ihr Euch durch ein Gefängnis kämpfen musstet, solltet Ihr nicht auslassen.>", sourceObjective = "Kehrt zu Samuel D. Kaltmann III. nach Boralus zurück und berichtet ihm von Eurer Entdeckung.", completion = "Oh, Ihr seid schon zurück? Das war aber verdächtig schnell. Wie ist es gelaufen?\n\n<Ihr erzählt, dass Ihr den Schrein gefunden habt und die Edelsteine ersetzen musstet.>\n\nDas hört sich ja nach einem richtigen Abenteuer an! Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55591] = { id = 55591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsverwüster" }
quests[55592] = { id = 55592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vielversprechender Anfang", description = "<Jetzt da der Schrein repariert ist, seid Ihr sehr begierig, den nächsten Schrein aufzusuchen.\n\nVielleicht hat Seshuli noch weitere Standorte gefunden.>", sourceObjective = "Kehrt zu Seshuli nach Dazar'alor zurück und berichtet ihr von Eurer Entdeckung.", completion = "Ihr meint, für den Schrein wurde der gleiche Juwelenschliff verwendet, den wir benutz'n? Beeindruckend, dass diese Bearbeitungsweise all die Jahre überlebt hat.\n\nWisst Ihr, vielleicht is' das der älteste bekannte Schliff der Geschichte. Vielleicht sogar der erste überhaupt!\n\nAber es is' schön zu hör'n, dass Ihr den Schrein reparier'n konntet. Möglicherweise müss'n die andern beid'n auch ausgebessert werd'n, schließlich sind die ja auch sehr alt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55593] = { id = 55593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkenntnisse über unsere Feinde", description = "Wir wissen nicht, was uns in diesem Land erwartet. Wir können nicht weitermarschieren, ohne zu wissen, was sie gegen uns auffahren werden.\n\nUnsere neuen Verbündeten kämpfen schon lange gegen die Naga. Sie wissen am besten, wie man sich durch diese Gewässer bewegt.\n\nSprecht mit Klingenmeister Okani und seht, ob er uns mehr dazu sagen kann, wie unser Gegner aufgestellt ist.", sourceObjective = "Sprecht mit Klingenmeister Okani, um mehr über die Naga in Nazjatar zu erfahren.", completion = "Ihr wollt mehr über die Naga in Nazjatar erfahren?\n\nIch befürchte, diese Gewässer sind mir genauso unbekannt, wie sie es Euch sind. Aber wir können uns trotzdem gegenseitig helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55594] = { id = 55594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufpoliert", description = "<Seshuli würde sicherlich gerne mehr über Eure Fortschritte bezüglich dieses Schreins erfahren.\n\nIhr seid der Ansicht, dass Ihr ihr so bald wie möglich Bericht erstatten solltet.>", sourceObjective = "Kehrt zu Seshuli nach Dazar'alor zurück und berichtet ihr von Eurer Entdeckung.", completion = "<Ihr berichtet Seshuli von Euren Entdeckungen am Schrein in Vol'dun.>\n\nDiese Wüste is' was für Irre, wenn Ihr mich fragt. Aber das Gute is', dass der Schrein noch steht und Ihr ihn reparier'n konntet.\n\nIch les' weiter in dem Tagebuch und versuch', noch mehr Informationen für Euch zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[55595] = { id = 55595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissensverfall", description = "Mein Klan ist nach Nazjatar gekommen und wollte die Nagakönigin vernichten.\n\nWir waren auf die Dunkelheit, die sie befehligt, aber nicht vorbereitet.\n\nUnsere Späher kannten dieses Land gut, aber ihr Wissen schwindet, jetzt, wo sie von den Streitkräften von Azshara kontrolliert werden.\n\nFindet und befreit unsere Späher und vielleicht habt Ihr noch eine Chance, an ihr Wissen zu gelangen.", sourceObjective = "Rettet Imara, Adaru und Umai aus den Klauen der willenszerstörenden Zoatroiden.", completion = "Ein hirnloser Sklave unserer Feinde zu sein ist ein schlimmeres Schicksal als der Tod.\n\nSo ein Leben hat keine Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[55596] = { id = 55596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fassung bewahren", description = "<Seshuli wird sicherlich sehr daran interessiert sein, von Eurer Untersuchung dieses Schreins zu erfahren.\n\nGanz besonders von dem Detail, dass Ihr Euch durch Atal'Dazar kämpfen musstet.>", sourceObjective = "Kehrt zu Seshuli nach Dazar'alor zurück und berichtet ihr von Eurer Entdeckung.", completion = "<Ihr berichtet Seshuli von Euren Erlebnissen am Schrein.>\n\nNach Atal'Dazar gereist, was? Das is 'n echt erstaunlicher Ort, so weit ich mich erinner.\n\nWie auch immer, die Reparatur des Schreins war ganze Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[55597] = { id = 55597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Ehre gebunden", description = "Es stimmt, dass mein Klan die Naga schon seit Generationen bekämpft, aber wir haben erst vor Kurzem unseren Kampf nach Nazjatar getragen.\n\nUnser Anführer wurde von der niederträchtigen Königin getötet, und jetzt bindet die Ehre meinen Klan an diesen tiefen Ozean.\n\nWir werden uns rächen oder bei dem Versuch, es zu tun, hier sterben. Das ist unser Weg.\n\nEuer Auftrag und unsere Aufgabe passen gut zusammen, also bekämpfen wir die Naga gemeinsam!\n\nTötet ihre Kämpfer und bringt uns so der Erfüllung unseres Versprechens einen Schritt näher.", sourceObjective = "Tötet 10 Naga in der Zanj'irbrandung und im Tiefseesklavenpferch.", completion = "Ihr kämpft wie ein Ankoaner. Ihr bringt meinem Klan mit Euren heutigen Taten Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[55598] = { id = 55598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir über die Naga wissen", description = "Ich stehe in Eurer Schuld, so viel ist klar.\n\nMein Kopf brummt immer noch vom Einfluss des Zoatroiden, aber ich fürchte, die anderen haben offensichtlichere Wunden davongetragen.\n\nTragt diese Salbe auf ihre Wunden auf und ich werde Euch nach meinem besten Wissen über die Naga informieren.", sourceObjective = "Kümmert Euch um die Wunden der Anokaner und hört Euch an, was Adaru über die Naga weiß.", completion = "Was auch immer in der Festung verborgen ist, es muss zerstört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55599] = { id = 55599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundungen im Geheimen", description = "Allein in die Festung zu gehen ist Selbstmord.\n\nDie Zanj'ir töten Unbekannte sofort.\n\nDie einzige Möglichkeit hineinzukommen, ohne dabei zu sterben, wäre, unter dem Einfluss eines Zoatroids hineinzugehen.\n\nDie willenlosen Sklaven werden direkt zur Arbeit geschickt.\n\nIhr müsst allen Aufforderungen folgen, oder sie werden bemerken, dass Ihr noch bei klarem Verstand seid.\n\nSobald die Zanj'ir glauben, dass Ihr willenlos seid, sollte es einfach sein, sich unauffällig in ihrem Territorium zu bewegen und ihr Geheimnis zu lüften.", sourceObjective = "Späht die Terrasse der Zanj'ir aus, während Ihr vorgebt, gedankengefesselt zu sein.", completion = "Was nützt Ihr uns, wenn Ihr nicht arbeitet?", sourceObjectiveStatus = "unverified-source-field" }
quests[55600] = { id = 55600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensättigen leicht gemacht", description = "Es wird Zeit, dass die Schnappdrachen gefüttert werden, aber das überlässt man lieber jemandem, den man nicht mehr unbedingt braucht.\n\nDie Biester fressen alles, sogar Euren Arm, wenn Ihr ihn nicht schnell genug wegzieht.\n\nZum Glück für Euch sind sie auf den Geschmack von Zitterstachelrogen gekommen.", sourceObjective = "Sammelt Zitterstachelrogen und füttert die wilden Schnappdrachen damit.", progress = "Kommt nicht wieder, bevor Eure Aufgabe erledigt ist.", completion = "Ich bin überrascht, dass sie Euch nicht verspeist haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55601] = { id = 55601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begehrte Kristalle", description = "Die Waffentruhe zu finden dürfte kein Problem sein, wenn wir erst die richtigen Hilfsmittel haben. Ein bisschen Licht und eine Menge biolumineszente Flüssigkeit, mehr brauchen wir nicht.\n\nDas scheint alles recht einfach zu sein, oder? Aber der Schlüssel ist der lichtbrechende Tiefseekristall.\n\nDer Stamm der Blutflossen ist ganz versessen auf diese Kristalle, also dürfte es Euch keine Schwierigkeiten bereiten, einen zu bekommen.", sourceObjective = "Holt einen Tiefseekristall von Horter Moarrgl.", progress = "Habt Ihr den Kristall gefunden?", completion = "Allmählich verstehe ich, warum die Blutflossen so versessen auf diese Kristalle sind. So einen Edelstein habe ich noch nie gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55602] = { id = 55602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wird wohl angelockt?", description = "<Dieser verfaulte, stinkende Köderklumpen ist die bevorzugte Nahrung von huschenden Zitteraalen. Vielleicht könnt Ihr in der Nähe befallene Gewässer finden?>", sourceObjective = "Beködert die aalverseuchten Gewässer.", progress = "Was habt Ihr für mich?", completion = "Ah, was haben wir denn hier? Das ist wirklich ein seltener Fund!\n\nIhr habt die Gewässer beködert, wie ich sehe!\n\nSeid nur vorsichtig.\n\nAale sind nicht die einzigen Kreaturen, die Ihr mit diesen Ködern anlocken werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55608] = { id = 55608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkstattprojekt", description = "Als Belohnung für all Eure Hilfe hier wollte ich diese Mechaspinne hier reparieren und Euch als Reittier überlassen.\n\nAber ich könnte noch mehr Eurer Hilfe brauchen, um dieses Projekt ans Laufen zu bekommen!\n\nIch brauche Teile von ein paar der Bots in der Nähe. Und vielleicht könnt Ihr mit Cork Schutzgart auf Bondos Hof sprechen und dabei eine Mechanobotzündung abstauben.", sourceObjective = "Besorgt Stahlverkleidung, Mehrbeinkettengetriebe und eine Mechanobotzündung.", progress = "Habt Ihr die Ersatzteile bereits gefunden?", completion = "Diese Teile reichen für den Anfang, aber es gibt immer noch eine Menge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[55609] = { id = 55609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Mechagon - Der Mecherschaffer", description = "Der Wahnsinn meines Vaters wird sich nicht auf diese Insel beschränken.\n\nKönig Mechagon erschafft ein riesiges Gerät, das den Fluch des Fleisches in ganz Azeroth umkehren kann!\n\nAlle Völker, die die Titanen erschaffen haben, werden in ihren Originalzustand versetzt. Wir Gnome würden komplett mechanisch. Zwerge und Troggs würden zu Stein. Vrykul zu Eisen.\n\nDie Liste ist noch länger, aber die meisten Völker stehen nicht einmal AUF der Liste. Alles, was die Titanen nicht erschaffen haben, wird vollkommen ausgelöscht.\n\nWir müssen König Mechagon aufhalten, bevor es zu spät ist!", sourceObjective = "Begebt Euch nach Mechagon und besiegt König Mechagon.", completion = "Dieser Roboter... diese KI... war nicht mein Vater.\n\nMein Vater ist an dem Tag gestorben, als er seinen Körper und Geist für die komplette Mechanisierung aufgab. An dem Tag, als er unser Volk verriet.\n\nDie Last des Anführers ruht nun schon seit geraumer Zeit auf meinen Schultern... Aber erst jetzt habe ich das Gefühl, sie guten Gewissens annehmen zu können.\n\nIch werde mein Volk mit Klugheit, Scharfsinn und in Demut führen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55613] = { id = 55613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55614] = { id = 55614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55617] = { id = 55617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsbelagerungsmaschine" }
quests[55618] = { id = 55618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herzschmiede", description = "Energieanstieg in der Herzschmiede weist auf die Präsenz von Schwarzdrachenessenz hin.\n\nEmpfehlung: Einleitung der Schmiedeaktivierungssequenz.", sourceObjective = "Sprecht mit MUTTER, um die Herzschmiede zu aktivieren.", completion = "Energiequelle akzeptiert. Schmiedenaktivierung abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55619] = { id = 55619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwertung für Euer Fahrzeug (optional)" }
quests[55622] = { id = 55622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch heute losfahren", description = "Die Reittiere sind alle aufpoliert und sehen großartig aus. Wir sind fast fertig!\n\nIch habe Pascal-K1N6 den Energiekernbauplan gegeben. Er ist bereit, uns einen neuen 500S-Kybergenikenergiekern zu bauen, wenn Ihr ihm die Einzelteile besorgt.\n\nWenn wir diesen Energiekern installieren, könnt Ihr noch heute mit diesem Bot davonfahren!", sourceObjective = "Besorgt einen 500S-Kybergenikenergiekern.", progress = "Habt Ihr den Kern bekommen?", completion = "Die stehlen nicht mehr von uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[55625] = { id = 55625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perlen von unvorstellbarer Macht", description = "Vor tausenden Jahren, als der Brunnen der Ewigkeit zerstört wurde und dieses Land in den Tiefen des Meeres versank, wurde ein gewaltiger Sturm magischer Energie entfesselt.\n\nÜberreste dieser magischen Energie existieren bis heute.\n\nSammelt die Perlen der uralten, manaversetzten Muscheln. Diese verzauberten Perlen könnten sich als mächtige Waffen in unserem Kampf gegen die Naga erweisen!", sourceObjective = "Sammelt 8 verzauberte Perlen.", progress = "Wir müssen jeden Vorteil im Kampf gegen die Naga nutzen.", completion = "Das habt Ihr gut gemacht. Ich spüre eine mächtige Energie, die von diesen Perlen ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[55630] = { id = 55630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickstart", description = "Glauben diese Gnome wirklich, sie müssten nur die Maschinen kaputtmachen, damit sie einen Goblin wie mich davon abhalten, herauszufinden, wozu die ganze Technologie hier gut ist?\n\nIch habe noch nie einen Schrotthaufen gesehen, der so kaputt war, dass der alte Skaggit und ich ihn nicht dazu bringen könnten, reibungsloser zu laufen als an dem Tag, als er gebaut wurde.\n\nIch sag Euch was. Ihr tut Euch mit Skaggit zusammen und seht zu, was Ihr wieder zusammenbauen könnt.\n\nIch werde mich in der Zwischenzeit mit unserer Gnomfreundin hier unterhalten und herausfinden, was sie über all die Technik hier weiß.", sourceObjective = "Repariert die Maschinerie der Kammer.", completion = "<Gazlowe spitzt die Ohren und lauscht einen Moment lang angestrengt.>\n\nDie Maschine klingt gut. Ein paar lockere Bolzen und fehlende Kabel, aber nichts, auf das wir nicht verzichten könnten.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[55632] = { id = 55632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mindestgröße einhalten!", description = "Ihr und die Schmiermaxen habt die Maschine schneller wieder betriebsbereit gemacht, als ich gedacht hätte.\n\nDie Gnomin, die wir gefangengenommen haben, will den Mund nicht aufmachen, aber das sollte kein Problem sein. Ich kann ab jetzt übernehmen.\n\nSagt mir Bescheid, wenn Ihr soweit seid. Dann drehe ich die Maschine bis zum Maximum auf und wir werden endlich sehen, wozu sie imstande ist.\n\nIch hoffe, sie druckt Goldmünzen...", sourceObjective = "Sagt Gazlowe, er soll das Gerät aktivieren.", progress = "Das ist die beste Verwendung für einen Gnom, die ich je gesehen habe!", completion = "Puh. Das war knapp, aber das Risiko wird sich gehörig auszahlen.\n\nHabt Ihr die beeindruckende Technologie gesehen, die König Mechagon trug? Die müssen wir in die Finger bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55633] = { id = 55633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versunkene Truhe", description = "<Diese durchnässte Truhe scheint durchaus noch zu retten zu sein, aber ihr Inhalt ist so schwer, dass man sie nicht fortbewegen kann.\n\nDer Schließmechanismus sieht aus, als ob er noch funktioniert.\n\nVielleicht gibt es einen Schlüssel in der Nähe...>", sourceObjective = "Findet den Messingschlüssel am Grund der Lagune.", progress = "<Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.>", completion = "<Es bedarf einiger Anstrengung, aber schließlich öffnet sich das Schloss...>", sourceObjectiveStatus = "unverified-source-field" }
quests[55635] = { id = 55635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stimme im Wind", description = "<Eine entfernte, mysteriöse Stimme durchdringt Euren Geist.>\n\nMeine Verzauberungen sind nicht verloren...\n\nFindet mich...\n\nDrustvar...\n\nFallhafen...", sourceObjective = "Findet den Ursprung der mysteriösen Stimme in Drustvar.", completion = "Sorgt Euch nicht, mein Freund. Ich werde Euch nichts tun. Aber ich habe ein Angebot für Euch.\n\nIch war nämlich einst eine Druidin, und das Einzige, was ich noch mehr liebte als die Pflege des Waldes und seiner Lebewesen, war die Verzauberkunst.\n\nAber dann wurde ich ermordet und dazu verflucht, über diese Halbinsel zu wandern, ohne den Fluss oder die Berge überqueren zu können, solange mein Körper noch existierte.\n\nWenn Ihr meinen alten Körper zerstört und mir helft, einen neuen zu erschaffen, werde ich Euch zeigen, wie man die Verzauberungsrute herstellt, die Ihr entzaubert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55636] = { id = 55636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Lebenswerk", description = "<Eine Stimme von jenseits des Todesschleiers flüstert Euch etwas zu.>\n\nIch habe mehr als tausend Jahre damit verbracht, die Geheimnisse des Arkanen zu erforschen, bevor die Große Zerschlagung unsere Welt in Stücke riss.\n\nIch hauchte mein Leben in all dieser Zerstörung aus und mein Werk ging verloren.\n\nDurchsucht das Gebiet nach meinen uralten Schriften und verschafft meinem Geist ewige Ruhe...", sourceObjective = "Sammelt 6 uralte Schriftrollen und 6 arkane Folianten.", progress = "Das Bücherregal wirkt leer...", completion = "Die arkanen Folianten und die uralten Schriftrollen haben ihren Platz im Bücherregal wieder eingenommen und Ihr fühlt Euch, als ob eine Last von Euren Schultern genommen wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[55637] = { id = 55637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arme Seelen in Not", description = "Die Große Zerschlagung hat zahllose Leben gefordert, als diese große Stadt in die Tiefen des Abgrunds gestürzt wurde.\n\nDie Glücklicheren unter uns starben schnell bei der Explosion, aber einige überstanden sie, nur um ihr Überleben kämpfen zu müssen, während die kalten, unerbittlichen Meereswogen über sie hinwegdonnerten.\n\nDas Schicksal dieser armen, unglücklichen Seelen ist bis heute schlimmer als der Tod. Sie ertrinken bis in alle Ewigkeit und sind dazu gezwungen, die Qual ihres Todes immer wieder zu durchleben.\n\nVerschafft ihnen Ruhe, damit sie endlich Frieden finden.", sourceObjective = "Verschafft 8 gequälten Seelen die letzte Ruhe.", completion = "Sie werden niemals das Leben zurückerlangen, das sie vor langer Zeit an jenem Tag verloren haben, aber wenigstens werden sie nicht länger leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55638] = { id = 55638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kelpbeerenwein keltern", description = "<Dies ist ein leeres Kelpbeerensaftfass.\n\nJemand ist in der Nähe, der sich über eine Wiederauffüllung freuen würde.>", sourceObjective = "Bringt Kelpbeerenwein zu Maedin in Maedins Herausforderung.", progress = "Habt Ihr mir etwas mitgebracht?", completion = "Oh, Ihr wisst genau, was dieses alte Mädchen mag!", sourceObjectiveStatus = "unverified-source-field" }
quests[55639] = { id = 55639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grobe Grube", description = "Der Wind flüstert von gefangenen Leuten in dieser Grube. Anscheinend befinden sich dort mehrere Mitglieder der Expedition.\n\nIch fürchte, nun ist es Euch überlassen, dort hinunterzusteigen und die Überlebenden zu retten.\n\nEs sollten insgesamt sechs sein... doch der Wind spricht davon, dass einer von den anderen weiter entfernt ist.\n\nBei unserem Glück wartet der letzte Überlebende ganz unten in der Grube.\n\nViel Glück, {name}. Und... achtet darauf, dass Euch keine Spinnen auf dem Weg heraus folgen.", sourceObjective = "Rettet 5 gefangene Expeditionsmitglieder.", completion = "Ralia Traumsucher ist eine Druidin des Zirkels des Cenarius, eines Druidenordens, der sich dem Schutze der Wildnis von Azeroth verschrieben hat.\n\nIch danke Euch für ihre Rettung. Ihre Hilfe wird gegen die Oger sehr nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[55640] = { id = 55640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision von Sturmwind", description = "Schwächt N'Zoth, indem Ihr in seinen Verstand dringt.", sourceObjective = "Schließt die Vision von Sturmwind ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[55645] = { id = 55645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzenbesuch", description = "Das ist es! Das legendäre Mechagon!\n\nDie größte Entdeckung unseres Zeitalters und Ihr seid hier, um meinen Erfolg mitzuerleben!\n\n<Tüftlermeister Oberfunks klopft mit stolzgeschwellter Brust seine Robe ab und lächelt zuversichtlich.>\n\nIch bin bereit, zum Volk von Mechagon zu sprechen. Ihr dürft mich begleiten.", sourceObjective = "Erkundet mit Tüftlermeister Oberfunks die nahegelegene Stadt.", completion = "Willkommen beim Rostbolzenwiderstand.", sourceObjectiveStatus = "unverified-source-field" }
quests[55646] = { id = 55646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Mechagon", sourceObjective = "Trefft Euch mit Gazlowe am Verlassenen Schrottplatz im Tiragardesund.", completion = "Bleibt in Deckung! Die Allianz war vor uns hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[55647] = { id = 55647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wände haben Ohren", description = "Schlechte Neuigkeiten. Wir sind zu spät.\n\nDie Kammer war bereits von der Allianz überlaufen, als wir eintrafen.\n\nZum Glück für uns gab es da drin eine gewaltige Erschütterung und einige von denen haben Hals über Kopf das Weite gesucht.\n\nDie meisten sind allerdings immer noch drinnen in der Kammer, einschließlich dieses Aufschneiders Tüftlermeister Oberfunks.\n\nGeben wir ihnen noch ein paar Minuten, um zu verschwinden, damit wir nicht aus allen Rohren feuern müssen.", sourceObjective = "Wartet darauf, dass die Allianz die Kammer verlässt.", progress = "Was haben die da unten gefunden?", completion = "Ich sagte Euch ja, dass Oberfunks ein Dummkopf ist.\n\nEin Boss muss seine Leute respektieren, sonst respektieren sie ihn nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[55648] = { id = 55648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist jetzt unsere Kammer", description = "Oberfunks ist weg und die Luft scheint rein zu sein. Gehen wir in die Kammer und finden wir heraus, was hier wirklich vorgeht.\n\nMechagon oder nicht, da drin sollte lieber etwas richtig gute Technik sein, damit dieser Ausflug keine Zeitverschwendung ist.", sourceObjective = "Führt Gazlowes Mannschaft in die Kammer.", completion = "Kinderspiel. Jetzt müssen wir nur noch all diese schicken Gnomenmaschinen wieder zum Laufen bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55649] = { id = 55649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechmachenschaften für Mechagon", description = "Also ist Mechagon nicht einfach nur ein Märchen? Ich muss zugeben, ich bin überrascht.\n\nAber wenn die Technologie, die der König trägt, ein Hinweis darauf ist, was wir da draußen einsacken können, dann irre ich mich wirklich sehr, sehr gerne!\n\nWir dürfen aber nichts überstürzen. Heute ist eine gute Mannschaft gestorben. Das passiert nicht nochmal unter meiner Leitung.\n\nTrefft mich und Skaggit im Hafen von Zuldazar und wir stellen diese Expedition richtig zusammen.", sourceObjective = "Reitet den Himmelsschleicher der Schmiermaxen zum Hafen von Zuldazar.", completion = "Ein gutes Gefühl, wieder im Revier der Horde zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[55650] = { id = 55650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur das Beste ist gut genug", description = "Ihr habt Gazlowe gehört. Der Boss will, dass seine Expedition reibungslos verläuft. Kein Pfusch, keine Schmiergelder.\n\nIch weiß, Ihr habt in der Vergangenheit mit Gallywix gearbeitet. So läuft das bei uns nicht.\n\nWir erwarten von unseren Mannschaften nur das Beste, also bezahlen wir sie nach Wert und behandeln sie gut. Dafür bekommen wir die besten Goblinmannschaften auf dem Planeten und sie laufen nicht zur Konkurrenz über.\n\nHier ist eine Liste, wen und was wir benötigen, um das hier auf die Beine zu stellen. Keine Sorge, Gazlowe kommt für die Kosten auf.", sourceObjective = "Besorgt alles, was für die Expedition nach Mechagon benötigt wird.", completion = "Das könnte die beste Mannschaft sein, die Gazlowe und ich je zusammengestellt haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[55651] = { id = 55651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Mechagon!", description = "Was immer uns an den Gestaden von Mechagon erwartet, mit dieser Mannschaft sind wir auf alles vorbereitet.\n\nIch mache mir keine Illusionen über den Empfang, den dieser verrückte König uns bereiten wird. Aus allen Rohren feuernd, da bin ich sicher.\n\nAlso nähern wir uns heimlich, still und leise mit diesem U-Boot. Wenn wir unauffällig bleiben, dient das unserer Sicherheit.\n\nWenn Ihr abreisefertig seid, sprecht mit Kapitänin Kruus.", sourceObjective = "Sprecht mit Kapitänin Kruus, um nach Mechagon zu reisen.", completion = "Lasst Euch von dem Gras nicht täuschen. Seht Euch die Bots an der Wasserlinie an. Die Stadt da vor uns. Das ständige Summen von Maschinen und Smog in der Luft.\n\nDieser Ort ist eine technologische Goldmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[55652] = { id = 55652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bilderbuchbucht", description = "Sieht so aus, als hätten wir's unbemerkt geschafft.\n\nSkaggits Mannschaft kann ihr Lager auf dem Strand da drüben aufschlagen, aber wir müssen erst sicher sein, dass sie sicher landen können.\n\nStarten wir einen kleinen Erkundungsflug, um herauszufinden, wie wir die Gegend erschließen können.\n\nDie Stadt da oben auf dem Berg sieht vielversprechend aus...", sourceObjective = "Verwendet den Jetpack, um mit Gazlowe und der Besatzung in die Bilderbuchbucht vorzudringen.", completion = "Diese ganze Insel wird im Handumdrehen uns gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[55655] = { id = 55655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55657] = { id = 55657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten der blutroten Schwingen", description = "Es ist nicht Alexstraszas Art, so lange keinen Kontakt aufzunehmen. Insbesondere dann nicht, wenn sich die geballte Essenz der Drachenschwarmmacht manifestiert.\n\nWährend sich unsere Verbündeten hier um die Verwundeten kümmern, müssen wir sofort nach der Lebensbinderin suchen.\n\nWenn Ihr bereit seid, brechen wir gemeinsam zum Zinnoberrefugium auf.", sourceObjective = "Sprecht mit Kalecgos, um zum Zinnoberrefugium zu fliegen. Findet dort Alexstrasza und ermittelt die Quelle der Bedrohung.", progress = "Wir sind wieder einmal auf Eure Hilfe angewiesen, Champion.", completion = "Wir stehen tief in Eurer Schuld. Ihr könnt auf die Unterstützung des roten Drachenschwarms bei Euren Rettungsbemühungen für Azeroth zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55658] = { id = 55658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise im Überfluss", description = "Bevor König Mechagon dieses Land für sich beansprucht hat, lebte hier jemand anderes. Die Historie eines vergessenen Volkes liegt unter Dreck und Müll vergraben. Mit Eurer Hilfe können wir etwas über die früheren Einwohner erfahren.\n\nSir Finley hat eine Stelle markiert, wo er ungewöhnliche Artefakte gesehen hat. Trefft ihn dort, um mögliche Hinweise zu finden.", sourceObjective = "Findet einen Hinweis auf die Geschichte der Insel.", progress = "Macht schon, die Geschichte wartet auf Euch!", completion = "Glänzende Leistung. Wir werden diesem Geheimnis im Handumdrehen auf den Grund gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55659] = { id = 55659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Zerschlagung", description = "Man trifft nicht jeden Tag auf die Überreste einer im Meer versunkenen Zivilisation!\n\nIch hätte mir nie träumen lassen, dass ich die Gelegenheit bekomme, die verschollene Stadt Nazjatar zu erkunden... und dann noch auf festem Boden!\n\nEs gibt hier viele Geheimnisse aufzudecken. Falls Ihr auf uralte Hochgeborenenartefakte stoßt, bringt sie mir bitte. Diese Relikte könnten uns wertvolle Hinweise bezüglich der Geheimnisse der Großen Zerschlagung liefern.\n\nIch habe das Gefühl, als ob wir bisher kaum die Oberfläche angekratzt haben...", sourceObjective = "Sammelt 10 Hochgeborenenrelikte.", progress = "Ganz gleich, welche Geheimnisse hier unter dem Meer verborgen wurden, sie warten jetzt darauf, enthüllt zu werden!", completion = "Ausgezeichnete Arbeit! Seht Euch all diese Hochgeborenenrelikte an, die Ihr gefunden habt! Ich werde sofort mit ihrer Untersuchung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55661] = { id = 55661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftiges mit Gift bekämpfen", description = "Es gibt viele Verwendungen für das Gift der Schnappdrachen.\n\nAuf der Hand liegt, ein Gegengift zur Heilung zu erschaffen oder Gift zu sammeln, mit dem man die Naga angreifen kann.\n\nBefassen wir uns mit der Wurzel des Problems, wortwörtlich.\n\nWendet etwas eingesammeltes Gift bei einem Terrorschlund an, um ihn zu schwächen. Tötet einen und bringt mir seine Fangzähne.\n\nIch glaube, ich kann dann mit etwas Nützlichem aufwarten.", sourceObjective = "Benutzt gesammeltes Gift, um einen Terrorschlund der Schnappdrachen zu schwächen und zu töten, und nehmt ihm die Fangzähne ab.", progress = "Habt Ihr die Fangzähne bekommen?", completion = "Ich muss aufpassen, dass ich mir damit keine Kratzwunde zuziehe.\n\nMit ein bisschen Erfahrung sollten wir ein Gegengift herstellen können... und vielleicht unsere eigene Waffe!", sourceObjectiveStatus = "unverified-source-field" }
quests[55662] = { id = 55662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Truhe", description = "<Die schwer verstärkte Truhe wurde von den Naga hergestellt und scheint durch eine Art magisches Schloss gesichert zu sein.\n\nMagische Verstärkung hin oder her, es wird immer noch ein Schlüssel benötigt, um das Schatzversteck aufzuschließen.\n\nDer Schlüssel befindet sich wahrscheinlich bei einem der Nagasoldaten in der Nähe.>", sourceObjective = "Findet den Schlüssel der arkanen Truhe.", progress = "<Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.>", completion = "<Die magische Barriere löst sich auf, als Ihr den Schlüssel ins Schloss steckt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55663] = { id = 55663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaputter Kontrolleur", description = "Es ist zu spät für mich, meine Freunde.\n\nDie Kontrolleure lassen uns ständig schuften und wir bekommen keine Pause.\n\nWir haben so viele verloren.\n\nBitte, befreit die anderen! Lasst sie nicht mein Schicksal erleiden!", sourceObjective = "Befreit die Sklaven und vernichtet den gnadenlosen Kontrolleur.", completion = "Jede Kelfinne, die wir freisetzen, schwächt die Naga etwas mehr.\n\nIch werde so viele heilen, wie ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[55664] = { id = 55664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefschlag für die Moral", description = "Das ist die Quelle unserer gesamten Verderbnis. \n\nDie Kelfinnen werden hierhergebracht und gebrochen. \n\nTrefft sie, wo es ihnen wehtut. Brecht ihre Macht und tötet alle Naga, die Ihr seht. Absolute Zerstörung!\n\nJeder Nadelstich, den wir ihnen versetzen, wird sie mehr schwächen.", sourceObjective = "Unterbindet all Aktivitäten im Repositorium der Shirakess.", completion = "Es wird eine Weile dauern, bis sie das aufgeräumt haben, {name}!\n\nIch liebe es einfach, sie in Panik umherlaufen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55665] = { id = 55665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der finstere Garten", description = "{name}, ich weiß, dass größere Schlachten vor uns liegen, aber diese Gärten sind entsetzlich.\n\nUnschuldige Kreaturen werden gefangen und dort zur Belustigung der Naga eingesperrt.\n\nUnd dann werden sie gefoltert, verändert und gebrochen... Ihr versteht schon.\n\nHelft mir, die Gefangenen der Naga zu befreien, und bestraft die Naga für ihre Überheblichkeit!", sourceObjective = "Tötet Naga und befreit die armen gefolterten Kreaturen, die in den Imperialen Gärten gefangen gehalten werden.", progress = "Habt Ihr da drinnen ordentlich Verwüstung angerichtet?", completion = "Ich bin mir ziemlich sicher, dass ich einen vorbeirennenden Otter kichern gehört habe.\n\nEure Kampffähigkeiten waren einfach bombig.", sourceObjectiveStatus = "unverified-source-field" }
quests[55667] = { id = 55667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[55668] = { id = 55668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[55669] = { id = 55669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Radio Receiver TBD" }
quests[55670] = { id = 55670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubflotte der Amathet" }
quests[55672] = { id = 55672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein historisches Chaos", description = "Der Text auf diesem Pergament scheint auf Tortollanisch verfasst zu sein. Ob einst Tortollaner auf dieser Insel gelebt haben?\n\nWir müssen schnell handeln, bevor die Kreaturen in dieser Gegend noch mehr Beweise vernichten. Sucht die Gegend nach tortollanischen Relikten ab.", sourceObjective = "12 Tortollanerrelikte gesammelt.", progress = "Macht schon, die Geschichte wartet auf Euch!", completion = "Prima Leistung. Wir werden diesem Geheimnis im Handumdrehen auf den Grund gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55681] = { id = 55681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbe markiert die Stelle", description = "<Das scheinen die Überreste einer Art Schatzkarte zu sein. Allerdings ist die Karte nicht mehr in bestem Zustand, nachdem sie jahrelang dem Meer ausgesetzt war.\n\nDer Karte zufolge soll der Schatz sich irgendwo in der Nähe befinden, aber auf der ruinierten Karte ist es unmöglich zu erkennen, um welchen Ort es sich genau handelt.>", sourceObjective = "Findet den vergrabenen Schatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[55683] = { id = 55683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Erinnerungen", description = "Kennen wir uns? Es tut mir leid... aber ich weiß Euren Namen nicht mehr.\n\nIch heiße... Arylina... glaube ich. Mein Gedächtnis ist so schwammig, seit es diese große Explosion gab, die uns unters Wasser geschleudert hat.\n\nOh! Seht! Ich kann die Sonne und die Sterne wieder sehen... Ich frage mich, was passiert ist?\n\nIch habe mal Tagebuch geführt, aber ich kann es nirgends finden. Wenn ich doch nur mein Tagebuch zurück hätte, dann bin ich sicher, dass ich mich an mehr erinnern könnte.\n\nWerdet Ihr mir helfen, es zu finden?", sourceObjective = "Findet Arylinas Tagebuch.", progress = "Wo hab ich nur das Tagebuch hingelegt?", completion = "Oh... Jetzt erinnere ich mich. Das ist alles vor so lange Zeit geschehen. Ich glaube, es ist Zeit, dass ich mich ausruhe...", sourceObjectiveStatus = "unverified-source-field" }
quests[55685] = { id = 55685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir kommen in Frieden... und Profitgier", description = "König Mechagon wird nicht gerade glücklich darüber sein, dass wir auf seiner Insel sind.\n\nAber ein grausamer König wie er wird auf jeden Fall Feinde haben. Ihr und ich wissen das besser als die meisten, oder?\n\nWährend Skaggit und die Mannschaft hier unseren Stützpunkt errichten, werden wir beide mögliche Verbündete suchen, um uns vor König Mechagons Zorn zu schützen.\n\nDie beiden Wachen sind zu dieser Müllhaldenstadt auf dem Hügel gerannt. Da oben riecht es nicht gerade... königlich. Sehen wir uns erstmal dort um.", sourceObjective = "Erkundet mit Gazlowe die Stadt in der Nähe.", completion = "Willkommen beim Rostbolzenwiderstand.", sourceObjectiveStatus = "unverified-source-field" }
quests[55686] = { id = 55686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwertung für Euer Jetpack (optional)" }
quests[55687] = { id = 55687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsmikrojetpack GG-118" }
quests[55688] = { id = 55688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsendes Mysterium", description = "Dieser Runenstein könnte von den Vrykul stammen. Ist es möglich, dass Vrykul einst diese Insel besucht haben? \n\nWo ein Runenstein ist, gibt es meist noch mehr. Die Wurzeln dieser Peitscher werden von Runensteinmagie angezogen. Wenn hier noch mehr vergraben sind, könnten die Peitscherwurzeln sie umschlungen haben!\n\nRodet die Peitscher und seht, ob sich in ihren Wurzeln Runensteine verfangen haben!", sourceObjective = "10 uralte Runensteine gesammelt.", progress = "Macht schon, die Geschichte wartet auf Euch!", completion = "Sehr schön. Wir werden die hier untersuchen und sehen, wohin uns das führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55694] = { id = 55694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da ist etwas im Wasser", description = "Die Ankoaner müssen sich nicht nur gegen die Bedrohung durch die Naga wehren, sondern auch gegen die Schrecken von N'Zoth. Wir haben schon früh gelernt, dass er, wenn wir seiner Infektion auch nur den geringsten Raum gewähren, wachsen und alles verderben wird.\n\nEtwas unglaublich Böses lauert in der Nähe der Wasserstraße, die diesen Ort durchfließt. Jemand muss sich darum kümmern.", sourceObjective = "Tötet das Auge des Verderbers.", completion = "Irgendwann wird etwas anderes seine Stelle einnehmen. Das ist wie Unkraut jäten. Es ist ein ständiger Kampf gegen eine Invasion.", sourceObjectiveStatus = "unverified-source-field" }
quests[55695] = { id = 55695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Duft nach neuem Gefährt", description = "Einmal pro Woche werden in Mechagon große Mengen Öl über den Auslass abgeschieden. Darum ist dieser Ort eine Giftmüllhalde!\n\nHeute haben sie Goldritzelpaste entsorgt. Das Zeugs ist wirklich bemerkenswert! Ich mache daraus Luftauffrischer. Damit riechen alle Reittiere, als wären sie brandneu!\n\nÜberprüft alle Rohre im Auslass und versucht, ein bisschen von dem Zeug einzusammeln.", sourceObjective = "Sammelt 8 Einheiten Goldritzelpaste.", progress = "Ich bräuchte immer noch diese Ritzelpaste.", completion = "Mir sind die Luftauffrischer ausgegangen; hiermit kann ich auf die Schnelle eine neue Ladung fertigmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55696] = { id = 55696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testfahrt", description = "Es gibt noch viel zu tun, aber es läuft! Wir müssen den Motor, die Bremsen und das Stellglied der Gyrobalance einem guten Test unterziehen. \n\nWollt Ihr eine Testfahrt machen und sehen, wie gut sie funktionieren?", sourceObjective = "Fahrt damit zum Kontrollpunkt, erreicht die Höchstgeschwindigkeit und führt eine Notbremsung aus.", completion = "Ich hatte schon Angst, Ihr würdet es nicht wieder zurückschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55697] = { id = 55697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen Beinarbeit", description = "Die Beine und Stoßdämpfer dieses Reittiers sind hinüber! Wir brauchen neue, wenn dieses Reittier loskrabbeln soll.\n \nVor einigen Wochen sind Bondo und seine Bande im Schrottknochenbau eingeritten und hofften, die Troggs in die Flucht zu schlagen. Die Troggs haben die Krabbler in Stücke gerissen! Die Teile dieser Krabbler liegen immer noch überall im Schrottknochenbau herum.\n\nSeht, ob Ihr uns ein paar dieser Teile von den Troggs besorgen könnt.", sourceObjective = "Sammelt 4 Mechaspinnenbeine und 12 Zehensprungfedern.", progress = "Wir brauchen diese Beine.", completion = "Mit diesen Teilen kommen wir unserem Ziel, dieses Ding zu reiten, wieder etwas näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[55701] = { id = 55701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappdrachenklauen", description = "Schnappdrachen sind wilde Kreaturen, die in Rudeln jagen. Durch ihre Anwesenheit in Nazjatar müssen wir zu jeder Zeit wachsam bleiben.\n\nSie sind raffinierte Wesen und ziehen es vor, ihre Beute aus dem Hinterhalt zu überfallen, wenn diese schwach oder verwundet ist. Wir müssen die Anzahl der Schnappdrachen in diesem Gebiet verringern.\n\nDas Letzte, was wir nach einem Kampf mit den Naga brauchen, ist ein Rudel blutrünstiger Schnappdrachen, die uns den Garaus machen!\n\nSpürt alle Schnappdrachen in der Nähe auf und bringt mir von jedem, den Ihr tötet, eine Klaue mit, damit ich ihre Anzahl im Blick behalten kann.", sourceObjective = "Sammelt 10 Schnappdrachenklauen.", progress = "Die Bedrohung durch die Schnappdrachen darf nicht unterschätzt werden.", completion = "Gute Arbeit, {name}. Je weniger Schnappdrachen wir in Nazjatar haben, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[55707] = { id = 55707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste gibts umsonst", description = "Das Rechengerät im Taschenformat kann Lochkarten lesen, um seine Leistung zu verbessern und zu modifizieren.\n\nIch könnte Euch eine Lochkarte geben, aber ein besonders hinterlistiger Trogg, Moch'k Achtdaumen, hat meine Tasche mit den Karten gestohlen.\n\nTötet Moch'k Achtdaumen, bergt mein Säckchen und ich kann Euch umsonst eine Lochkarte überlassen.", sourceObjective = "Tasche mit Lochkarten gefunden.", progress = "Holt die Tasche zurück!", completion = "Für jemand mit so wenig Mechanisierung seid Ihr ziemlich erstaunlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[55708] = { id = 55708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgewertet", description = "Nun lasst Euch mal ansehen, {race}...\n\n<Christys mechanische Augen mustern schnell Euren Körper.>\n\nNicht so beeindruckend, wie ich gehofft hatte.\n\nKönig Mechagons Armeen sind komplett mechanisiert. Aber Ihr... Ihr habt einen gewaltigen Überschuss an Fleisch und dazu passende Maschinendefizite.\n\nJa, wir müssen einfach ein paar Änderungen vornehmen... Vielleicht eine neurokraniale Verbesserung!\n\nBringt mir ein paar Mikrozahnräder von den Motorspinnen in der Nähe, dann kriege ich Euch schon hin!", sourceObjective = "Sammelt 20 Mikrozahnräder.", progress = "Ihr müsst König Mechagon strategisch besiegen. Beschafft mir diese Teile.", completion = "Eure erste Verbesserung! Probiert sie mal aus, bevor wir sie dauerhaft befestigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55712] = { id = 55712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwertung für Euren A.T.O.M.I.K. Mk. II (optional)" }
quests[55713] = { id = 55713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditions-A.T.O.M.I.K. Mk. II" }
quests[55714] = { id = 55714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerentruhe", description = "<Die schwer verstärkte Truhe wurde von den Naga hergestellt und scheint durch eine Art magisches Schloss gesichert zu sein.\n\nMagische Verstärkung hin oder her, es wird immer noch ein Schlüssel benötigt, um das Schatzversteck aufzuschließen.\n\nDer Schlüssel befindet sich wahrscheinlich bei einem der Nagasoldaten in der Nähe.>", sourceObjective = "Findet den Schlüssel der Leerentruhe.", progress = "<Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.>", completion = "<Die magische Barriere löst sich auf, als Ihr den Schlüssel ins Schloss steckt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55715] = { id = 55715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speisung der Vielen", description = "Wenn wir unsere Arbeit richtig machen, haben wir immer mehr Mäuler zu stopfen!\n\nWenn Ihr mir mit meinen Vorräten helft, könnten wir noch mehr versorgen.\n\nGroße, starke Freunde braucht diese Revolution!", sourceObjective = "Sammelt 10 Stücke Tiefenrochenfleisch.", progress = "Haben wir genug Protein?", completion = "Ihr seid eine große Hilfe! Vielleicht finde ich im Laufe der Zeit doch noch Gefallen an Euch Landkreaturen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55717] = { id = 55717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Heldentaten", description = "Die Karte, die Ihr gefunden habt, war eine goldene, seltene Huolon! \n\nIch glaube, die Karte gehörte Adalin Hüfthoch, einem unserer jüngsten Mitglieder der Forscherliga. Wenn er sie verloren hat, könnten er und unsere anderen Nachwuchskräfte in Schwierigkeiten stecken!\n\nWir müssen Leona Nebelrufer, Dunkin Kieferbruch und Adalin Hüfthoch auf der Stelle finden!", sourceObjective = "Rettet Leona Nebelrufer, Dunkin Kieferbruch und Adalin Hüfthoch.", completion = "Ihr seid wirklich der Held, über den alle reden!", sourceObjectiveStatus = "unverified-source-field" }
quests[55718] = { id = 55718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merkwürdige Entdeckung", description = "<Ein sehr alter, von den Nachtelfen stammender Ring. Er wirkt auf dieser Insel deplatziert. Vielleicht weiß Elise Sternensucher, was davon zu halten ist.>", sourceObjective = "Bringt den Ring zu Elise Sternensucher.\n\nBereitgestellter Gegenstand:", completion = "Das wirft mehr Fragen über die Vergangenheit dieser Insel auf, als es Antworten gibt.\n\nIch werde mir das näher ansehen, wenn ich nach Eisenschmiede zurückkehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[55719] = { id = 55719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein paar Seesterne", description = "Unsere Späher haben Seesternschuppen als Tarnung verwendet. Das Problem ist, dass die Schuppen viel zu schnell zerfallen. Wir brauchen mehr Schuppen, wenn wir die Bewegungen der Naga im Blick behalten wollen.\n\nFalls Ihr zufällig auf Engelsschuppenseesterne stoßt, bringt sie bitte so bald wie möglich zum Rüstmeister.", sourceObjective = "Sammelt 3 Engelsschuppenseesterne.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55720] = { id = 55720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein paar Klumpen Seetang", description = "Wir haben so viele Verwundete und unser Bestand an Seetangbandagen ist gefährlich niedrig. Wenn Ihr klebrigen Seetang findet, bitte gebt ihn beim Rüstmeister ab.", sourceObjective = "Sammelt 3 Klumpen klebrigen Seetangs.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55721] = { id = 55721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein paar Tangknospen", description = "Wir brauchen Rationen für unsere Truppen. Auch wenn Tangknospen nicht so gut schmecken wie andere Alternativen, so sind sie doch nahrhaft und in der Nähe von Tangwäldern reichlich vorhanden. Deshalb sind sie unsere erste Wahl als Rationen.\n\nFalls Ihr zufällig welche in Nazjatar findet, liefert sie bitte beim Rüstmeister ab. Am besten sind die, die gerade frisch vom Tang abgefallen sind.", sourceObjective = "Sammelt 3 abgefallene Tangknospen.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55723] = { id = 55723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein paar Karpfen", description = "Unsere einheimischen Fischarten sind in Gefahr! Solltet Ihr einen Fisch an Land entdecken, bringt ihn bitte sofort in den nächsten See, Strom oder Fluss zurück. Arterhaltung ist jedermanns Pflicht!", sourceObjective = "Bringt 3 zappelnde Karpfen zurück ins Wasser.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55724] = { id = 55724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein paar Tiefenkorallenknospen", description = "Für viele Spezies sind die Tiefenkorallenknospen an den hohen Säulen im Osten eine wichtige Nahrungsquelle, besonders für Tiefenrochen. Wir nutzen diese Knospen als Köder für Tiefenrochen, um sie als Reittiere zu fangen. Unsere Vorräte sind aber sehr gering. Wir werden also nicht die Luftunterstützung bieten können, die wir in Nazjatar brauchen werden.\n\nKönntet Ihr einige Tiefenkorallenknospen sammeln und sie beim Rüstmeister abgeben? Ihr werdet sicher dafür entlohnt.", sourceObjective = "Sammelt 3 Tiefenkorallenknospen.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55725] = { id = 55725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein wenig Ringelblatt", description = "Unsere Arzneimittelvorräte sind gefährlich niedrig. Solltet Ihr Ringelblatt finden, überlasst Eure Vorräte bitte dem Rüstmeister.\n\nIch sollte Euch warnen, dass Ringelblatt höchst giftig ist. Bitte geht vorsichtig damit um. Symptome einer Ringelblattvergiftung sind unter anderem Zornausbrüche, plötzliches Ansteigen der Körperkraft und impulsive Mordgedanken. Wenn Ihr dem Gift ausgesetzt wart, solltet Ihr die nächsten Naga aufsuchen und Eure mörderische Energie für einen guten Zweck einsetzen.", sourceObjective = "Sammelt 3 Stücke giftiges Ringelblatt.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55726] = { id = 55726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein paar Kegelmuscheln", description = "Wenn wir uns gegen die Naga wappnen wollen, brauchen wir weit mehr Vorräte und Rüstzeug. Der größte Teil unserer Rüstungen und Waffen ist aus Kegelmuscheln gefertigt. Diese sind leicht, robust und kommen in dieser Region im Überfluss vor. Dennoch schrumpfen unsere Vorräte, und unsere Truppen brauchen Unterstützung.\n\nJeder, der undurchdringliche Kegelmuscheln bei sich hat, soll seine Vorräte beim Rüstmeister abgeben.", sourceObjective = "Sammelt 3 undurchdringliche Kegelmuscheln.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55727] = { id = 55727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Ein wenig Treibgut", description = "Ich habe im Sand im Westen Berge von Treibgut gesehen. Könntet Ihr mal nachsehen, ob sich in den Trümmern etwas Nützliches findet? Das könnte uns weiterhelfen. Seid aber gewarnt: Das ist ein Brutplatz der Hydras. Sie sind dort besonders aggressiv geworden, seit das Wasser zurückgegangen ist.\n\nSobald Ihr ein paar Vorräte gesammelt habt, könnt Ihr Euch beim Rüstmeister melden. Er wird Euch eine Belohnung geben.", sourceObjective = "Sammelt 3 Haufen Treibgut.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55728] = { id = 55728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkte Truhe", description = "<Die schwer verstärkte Truhe wurde von den Naga hergestellt und scheint durch eine Art schweres Schloss gesichert zu sein.\n\nVerstärkung hin oder her, es wird immer noch ein Schlüssel benötigt, um das Schatzversteck aufzuschließen.\n\nDer Schlüssel befindet sich wahrscheinlich bei einem der Nagasoldaten in der Nähe.>", sourceObjective = "Findet den Schlüssel der verstärkten Truhe.", progress = "<Die Truhe ist verschlossen und muss mit einem Schlüssel geöffnet werden.>", completion = "<Ihr dreht den Schlüssel und hört, wie die schweren Riegel der Truhe mit beachtlicher Kraft zurückschnappen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55729] = { id = 55729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Widerstand braucht EUCH!", description = "Der Rostbolzen ist normalerweise nicht so konfus.\n\nKönig Mechagon hat letzte Nacht unsere Stadt angegriffen. Seine mechanischen Armeen haben viele Mitglieder des Rostbolzenwiderstands gefangen genommen und so viel wie möglich zerstört, bevor wir sie zurückschlagen konnten.\n\nDie Gefangenen werden im Schrottwattdepot abgefertigt. Danach werden sie in die unterirdische Stadt von König Mechagon gebracht... um komplett mechanisiert zu werden.\n\nDas dürfen wir nicht zulassen. Werdet Ihr mir helfen, sie zu retten?", sourceObjective = "Begebt Euch mit Prinz Erazmin zum Schrottwattdepot.", completion = "Hier werden alle Gefangenen abgefertigt, bevor sie zur Umprogrammierung in König Mechagons Stadt geschickt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55730] = { id = 55730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Widerstand retten", description = "König Mechagon ist erbarmungslos effizient. Er setzt Ressourcen nur dafür ein, diejenigen zu entführen, die er für wertvoll hält.\n\nDen Rest... entsorgt er.\n\n<Prinz Erazmin verzieht das Gesicht.>\n\nWir kümmern uns ein anderes Mal um meinen Vater, König Mechagon.\n\nDiese Information ist deswegen unmittelbar bedeutsam, weil wir durch die Berechenbarkeit meines Vaters davon ausgehen können, dass unsere besten Wissenschaftler, Ingenieure und Tüftler irgendwo lebend in diesem Depot gefangen sein dürften.\n\nWir werden sie finden und befreien.", sourceObjective = "Rettet die Mitglieder des Rostbolzenwiderstands.", completion = "Mein Vater ist kurzsichtig. Er macht den Wert von Individuen an deren augenblicklichem Zustand fest. Ihm entgeht ihr wahres Potential.", sourceObjectiveStatus = "unverified-source-field" }
quests[55731] = { id = 55731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Armeen meines Vaters", description = "Mein Vater war einst ein guter Anführer. Er stellte sich eine glänzende Zukunft für sein Volk vor und tat alles in seiner Macht Stehende, um uns dabei zu helfen, sie zu erreichen.\n\nDoch als seine Vision begann, sich von der seines Volks zu unterscheiden, gelang es ihm nicht, sich anzupassen. Stattdessen wurde er unnachgiebig und zwang seinen Willen anderen auf.\n\nIn geheimen Experimenten begann er, die Körper derjenigen komplett zu mechanisieren, die ihm Widerstand leisteten.\n\nEs war furchtbar mitanzusehen... von den ursprünglichen Gnomen, die ihm freiwillig gefolgt waren, war nichts mehr übrig.\n\nNur Roboter blieben. Sklaven.", sourceObjective = "Tötet 12 Mechagontruppen im Schrottwattdepot.", completion = "Wenn wir meinen Vater nicht aufhalten, werden wir alle das Schicksal dieser armen Gnome teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55732] = { id = 55732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alte Narbe", description = "Wir haben ein neues Problem, Champion. Es hat sich noch eine schwere Wunde aufgetan, dieses Mal am Mahlstrom!\n\nDie Schamanen dort sind in großen Schwierigkeiten und brauchen unsere Hilfe!\n\nSprecht mit MUTTER, um zum Mahlstrom zu reisen. Ich treffe Euch dann dort.", sourceObjective = "Sprecht mit MUTTER, um zum Mahlstrom zu reisen.", completion = "Ich wusste, es würde übel sein, aber ist sogar noch schlimmer!", sourceObjectiveStatus = "unverified-source-field" }
quests[55734] = { id = 55734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bohrmaschinenbau", description = "<Prinz Erazmin durchsucht die Ressourcen, die Ihr gemeinsam gesammelt habt.>\n\nJa... Es sieht so aus, als ob das genügt, um die Bohrmaschine wieder betriebsfähig zu machen.\n\nIch werde mit meinen Ersatzteilen tun, was ich kann, aber Ihr müsst mit Euren den Rest erledigen.\n\nWenn Ihr fertig seid, kehrt zu der kaputten Bohrmaschine zurück, die wir gefunden haben, und öffnet sie.\n\nGemeinsam werden wir sie in null Komma nichts wieder betriebsbereit haben.", sourceObjective = "Steuert Ersatzteile und Energiezellen zu dem Konstruktionsprojekt der kaputten Bohrmaschine bei.", progress = "Ihr habt doch nicht Eure Ersatzteile verloren, oder?", completion = "Haltet Ausschau nach anderen Konstruktionsprojekten auf der Insel.\n\nEs gibt in Mechagon immer irgendetwas zu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55735] = { id = 55735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Mahlstroms", description = "Die Schamanen des Irdenen Rings sind mächtig, aber das hier ist selbst für sie zu viel! Und anscheinend sind einige von ihnen noch da unten gefangen.\n\nVerwendet genau wie bei Nordrassil Euer Herz von Azeroth, um die Wunden zu versiegeln. Und schaltet alle durchgedrehten Elementare aus, bevor sie noch mehr Unheil anrichten.", sourceObjective = "Besiegt die Azeritelementare und versiegelt Azeroths Wunden beim Mahlstrom.", completion = "Das war knapp! Ich weiß nicht, was vielleicht noch passiert wäre, wenn Ihr die Ausweitung dieser Wunden nicht verhindert hättet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55736] = { id = 55736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen beim Widerstand", description = "Das Leben im Rostbolzenwiderstand ist nicht leicht, {name}.\n\nAber es ist Euer Leben. Wir werden Euch nicht herumkommandieren oder zum Kampf zwingen. Mechagon ist ein Land unbegrenzter Möglichkeiten und Ihr dürft alle Ziele verfolgen, die Ihr möchtet.\n\nSolltet Ihr allerdings für Vorschläge offen sein, welche Verbesserungen für Euch vordringlich wären, werden ich oder alle anderen Mechagnome der Stadt Euch gerne beraten, was Eure momentanen Schwächen angeht.\n\nAber für den Moment bitte ich Euch nur, mich zu meiner Werkstatt zu begleiten.", sourceObjective = "Macht einen Rundgang durch den Rostbolzen mit Prinz Erazmin.", completion = "Ich frage mich, was Ihr als nächstes tun wollt?", sourceObjectiveStatus = "unverified-source-field" }
quests[55737] = { id = 55737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur azerichtigen Zeit", description = "Ihr habt es geschafft! Ihr habt verhindert, dass der Schaden noch schlimmer wird!\n\nDer Mahlstrom wird für Azeroth immer ein geschichtsträchtiger und schmerzvoller Ort bleiben, aber mit jedem kleinen Schritt, den wir tun, sieht die Welt wieder ein Stück besser aus. Wer weiß, vielleicht gelingt es uns eines Tages sogar, Silithus zu heilen!\n\nWir treffen uns wieder in der Herzkammer. MUTTER interessiert bestimmt, was hier geschehen ist.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Herzuntersuchung abgeschlossen. Zusätzliche Azeritverstärkung aktiviert.", sourceObjectiveStatus = "unverified-source-field" }
quests[55739] = { id = 55739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Kammer", description = "Das Herz von Azeroth wird jeden Tag stärker, und das macht einen Riesenunterschied.\n\nBegebt Euch zur Herzkammer, Champion. Wir brauchen Eure Talente.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Das Herz von Azeroth erstaunt mich doch immer wieder. Gut gemacht, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[55742] = { id = 55742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haufen korrodierter Teile" }
quests[55743] = { id = 55743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder Wiederverwertung", description = "<Recycling macht Spaß und ist lukrativ. Der Wiederverwertisierer DX-82 ist bereit, noch mehr Metallschrott aufzunehmen.>", sourceObjective = "Sammelt 1 Bündel wiederverwertbarer Teile.", progress = "<WARNUNG 3.6.4 - Y: Alle Gliedmaßen von den Türen fernhalten, um irreversible Wiederverwertisierung selbiger zu vermeiden.>", completion = "Ihr habt das Bündel Teile in den Wiederverwertisierer DX-82 gegeben. Die Türen schließen sich und die Maschine nimmt mit einem anschwellenden, summenden Geräusch aus dem Inneren die Arbeit auf. Die Frequenz des Geräuschs wird immer höher und steigert sich zu einem hohen Sirren. Die heftig vibrierende Maschine scheint jeden Augenblick explodieren zu wollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[55750] = { id = 55750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lady Naz'jess", description = "Gesucht wegen Angriffen auf die Allianz!\n\nLady Naz'jess ist für mehrere Raubzüge und Überfälle auf unsere Soldaten verantwortlich. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Lady Naz'jess.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Lady Naz'jess war eine gefährliche Gegnerin und eine hochrangige Kommandantin der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[55751] = { id = 55751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Wassers", description = "Hier oben sieht man so einiges.\n\nSogar das Wasser ist dem Willen der Naga sklavisch ergeben.\n\nIch glaube, dass wir ihnen abseits von hier dabei helfen können, sich neu zu orientieren.\n\nBringt mit, was Ihr tragen könnt!", sourceObjective = "Sammelt 15 lebende Tröpfchen von Wasserelementaren auf der Terrasse der Azsh'ari.", progress = "Habt Ihr sie befreit?", completion = "Gut gemacht, {race}!\n\nWir hoffen einfach das Beste!", sourceObjectiveStatus = "unverified-source-field" }
quests[55752] = { id = 55752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam sind wir stark", description = "Die Arbeit, die Ihr bei der Stärkung des Herzens von Azeroth geleistet habt, kann nicht genug gelobt werden. Durch diese Macht haben wir vielleicht doch eine Chance, die Welt zu retten.\n\nDer Kampf war gewiss lang und es gibt noch viel zu tun, aber jetzt haben wir erstmal ein kleines Geschenk für Euch!\n\nGebt mit Bescheid, wenn Ihr bereit seid, Champion.", sourceObjective = "Sprecht mit Magni.", progress = "Ist das nicht unglaublich, Champion? Wer weiß, wie mächtig das Herz noch wird!", completion = "Erstaunlich, nicht wahr? Die Drachenschwärme zur Unterstützung von Azeroth wieder vereint zu sehen. Einige sind ganz schön mitgenommen, aber sie kämpfen immer noch.\n\nErweist Euch ihrer Gaben würdig, Champion von Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[55753] = { id = 55753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robo-Raubkopie", description = "Ich muss den Hauptkraftkern neu bauen. Es handelt sich um einen 500S-Mekronik, also brauche ich den Schaltplan, um die Arbeit machen zu können. Die einzige Person, die meines Wissens eine Ausgabe davon hat, ist Bondo Brummblock.\n\nWir werden Bondos Hilfe brauchen, um das hier abzuschließen. Vielleicht könnt Ihr ihn bitten, uns seinen Bauplan zu leihen.", sourceObjective = "Besorgt den Energiekernbauplan von Bondo Brummblock.", progress = "Habt Ihr eine Abmachung mit Brondo geschlossen?", completion = "Großartige Arbeit, {name}. Jetzt müssen wir nur noch diesen Energiekern neu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55763] = { id = 55763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Meredy Weidmannsheil", description = "Meredy Weidmannsheil, die Magierin unserer Expedition, wird von den Harpyien gefangen gehalten!\n\nWir müssen ihr Ritual aufhalten und Meredy retten.\n\nGeht Ihr voraus. Kee-La und ich werden Euch unterstützen, wenn die Lage ernst wird.", sourceObjective = "Rettet Meredy Weidmannsheil vor dem nekromantischen Ritual der Harpyien.", completion = "Ihr habt mir wirklich ein grausiges Schicksal erspart! Als Magierin dachte ich immer, dass meine eigenen Zauber zu meinem Verhängnis werden würden und keine Harpyie!", sourceObjectiveStatus = "unverified-source-field" }
quests[55764] = { id = 55764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpyienausdünnung", description = "Die Harpyien bereiten einen schrecklichen Angriff vor, {name}.\n\nSie wollen unsere Verbündeten in unserem Lager überraschen!\n\nDie Harpyien wollen sich auf sie stürzen, sie schnappen und in ihre Nester bringen... um sich an ihnen zu laben.\n\nWir müssen sie aufhalten. Tötet die Harpyien und ihre Worgs, damit ihnen die Streitkräfte für einen Angriff fehlen.", sourceObjective = "Besiegt 10 Harpyien und ihre Verbündeten.", progress = "Wir müssen alles in unserer Macht Stehende tun, um die Bedrohung durch die Harpyien zu bekämpfen. Schaltet sie und ihre Worgs aus.", completion = "Nun sollte unser Lager vorerst sicher sein. Was diese Oger auch planen, wir müssen uns beeilen und es stoppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55765] = { id = 55765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeziefer, in rauen Mengen!", description = "Ihr habt ein Problem mit mechanischem Ungeziefer, also sind die Raunacken hier, um das Chaos zu beseitigen!\n\nWenn Ihr mich fragt, muss eine Königin hinter all dem stecken. Wir werden reingehen und eine Menge Ungeziefer töten, bis wir die Anführerin finden, die dahintersteckt.\n\nHorde oder Allianz, das macht keinen Unterschied. Heute seid Ihr bei den Raunacken. Töten wir etwas Ungeziefer!", sourceObjective = "Löscht 20 Motospinnen aus.", completion = "Ihr habt zurückgeschlagen. Ihr seid ein Raunacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[55766] = { id = 55766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie mauschelt mit Muscheln", description = "Suva ist so stolz auf ihre Muscheln.\n\nNach allem, was sie für unser Volk getan hat, ist es das Mindeste, was wir tun können, ihr mit Nachschub zu helfen!\n\nGeht den Hügel hinunter und sammelt einige der glänzendsten Muscheln, die Ihr finden könnt!\n\nIhr werdet ihr eine Riesenfreude machen.", sourceObjective = "Sammelt 8 Muscheln.", progress = "<Aufgeregtes Klicken und Quietschen.>", completion = "<Suvas Fühler zucken freudig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55767] = { id = 55767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irreführung", description = "Wir sind in Freundschaft gekommen, aber diese widerlichen Murlocs sind über uns hergefallen und haben meinen Schatz gestohlen.\n\nSie haben ihn in eine der riesigen Muscheln geworfen und sind dann in das Dorf geflohen.\n\nSie schaffen diese Muscheln von einem Ort zum anderen und jetzt weiß ich nicht mehr, wo mein Schatz ist!\n\nKönntet Ihr mir vielleicht helfen?", sourceObjective = "Findet Danis Schatz.", progress = "Habt Ihr es geschafft?", completion = "Das ist er! Dexter war ja so traurig!\n\nSie dachten, sie wären so schlau.\n\nDas nächste Mal bekommen sie einen Tritt gegen die Rückenflosse.", sourceObjectiveStatus = "unverified-source-field" }
quests[55768] = { id = 55768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junger Seetang", description = "Es gibt ein außergewöhnliches Kelp, das in der Nähe von Schloten wächst.\n\nUnsere Heiler verwenden es, um bei der Behandlung unserer Freunde in Neuheim zu helfen.\n\nMeine Spezies hat dort unten keine große Chance, aber Ihr schon!\n\nSammelt einige der Schlotkelpsprossen im Drachenzahnbecken und bringt sie Nevin.", sourceObjective = "Sammelt 10 Schlotkelpsprossen.", progress = "Habt Ihr das außergewöhnliche Schlotkelp gefunden?", completion = "Die sind perfekt! \n\nWer Tang, der Tang!", sourceObjectiveStatus = "unverified-source-field" }
quests[55770] = { id = 55770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kommandant Sarj'eth", description = "Gesucht wegen Angriffen auf die Allianz!\n\nKommandant Sarj'eth ist für mehrere Raubzüge und Überfälle auf unsere Soldaten verantwortlich.\n\nZuletzt wurde er in der Umgebung dieses Steckbriefs gesehen.\n\nÄußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Kommandat Sarj'eth.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Sarj'eth war ein gefährlicher Gegner und ein hochrangiger Kommandant der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[55771] = { id = 55771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lord Ha'kass", description = "Gesucht wegen Angriffen auf die Allianz!\n\nLord Ha'kass ist für mehrere Raubzüge und Überfälle auf unsere Soldaten verantwortlich.\n\nZuletzt wurde er in der Umgebung dieses Steckbriefs gesehen.\n\nÄußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Holt den Kopf von Lord Ha'kass.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Lord Ha'kass war ein gefährlicher Gegner und ein hochrangiger Kommandant der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[55772] = { id = 55772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lady Narjiss", description = "Gesucht wegen Angriffen auf die Allianz!\n\nLady Narjiss ist für mehrere Raubzüge und Überfälle auf unsere Soldaten verantwortlich. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Lady Narjiss.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Lady Narjiss war eine gefährliche Gegnerin und eine hochrangige Kommandantin der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[55773] = { id = 55773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gler'thogg", description = "Gesucht wegen Angriffen auf die Allianz!\n\nGler'thogg ist für grausame Morde an einigen unserer besten Soldaten verantwortlich. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft Gler'thoggs Auge.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Gler'thogg war ein gefährlicher Gegner und ein hochrangiger Kommandant der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[55774] = { id = 55774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Inquisitor Ithriza", description = "Gesucht wegen Angriffen auf die Allianz!\n\nInquisitor Ithriza ist für mehrere Raubzüge und Überfälle auf unsere Soldaten verantwortlich.\n\nZuletzt wurde er in der Umgebung dieses Steckbriefs gesehen.\n\nÄußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Inquisitor Ithriza.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Inquisitor Ithriza war ein gefährlicher Gegner und ein hochrangiger Kommandant der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[55775] = { id = 55775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Haggronar", description = "Gesucht wegen Angriffen auf die Allianz!\n\nHaggronar ist für grausame Morde an einigen unserer edelsten Soldaten verantwortlich. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft den Kopf von Haggronar.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Haggronar hat unsere Soldaten seit dem Tag unserer Ankunft in Nazjatar in Angst und Schrecken versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55776] = { id = 55776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Emorneth", description = "Gesucht wegen Angriffen auf die Allianz!\n\nEmorneth ist für grausame Morde an einigen unserer besten Soldaten verantwortlich. Äußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Tötet Emorneth.", completion = "Gut gemacht, {class}. Emorneth hat unsere Soldaten seit dem Tag unserer Ankunft in Nazjatar in Angst und Schrecken versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55777] = { id = 55777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Braxicus", description = "Gesucht wegen Angriffen auf die Allianz!\n\nBraxicus ist für grausame Morde an einigen unserer edelsten Soldaten verantwortlich.\n\nZuletzt wurde er in der Umgebung dieses Steckbriefs gesehen.\n\nÄußerste Vorsicht ist geboten!\n\nMeldet Euch nach Abschluss dieser Mission bei Leutnant Hawkins für Eure Belobigung.", sourceObjective = "Beschafft Braxicus' riesige Klaue.", progress = "Habt Ihr etwas zu berichten?", completion = "Gut gemacht, {class}. Braxicus hat unsere Soldaten seit dem Tag unserer Ankunft in Nazjatar in Angst und Schrecken versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55778] = { id = 55778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Gefahr", description = "{name}, Geistwandler Ussoh hat mir eine verstörende Vision offenbart, die sich um Baine Bluthuf dreht.\n\nEr hat darum gebeten, dass Ihr so schnell wie möglich mit ihm sprecht.\n\nKommt danach zurück zu mir. Es gibt viel zu besprechen.", sourceObjective = "Sprecht mit Geistwandler Ussoh.", completion = "Sylvanas wird Baine Bluthuf bald hinrichten lassen... wenn wir nichts unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55779] = { id = 55779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Richtern und Henkern", description = "Kommt. Es ist Zeit, einen Freund zu retten.", sourceObjective = "Schließt das Szenario \"Von Richtern und Henkern\" ab.", completion = "Dem Sonnenbrunnen sei Dank, dass Ihr Baine retten konntet, {name}. Danke.\n\nJaina Prachtmeer ist ihm ebenfalls zu Hilfe geeilt. Interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[55780] = { id = 55780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Verbündete", description = "Sylvanas war meine Waldläufergeneralin. Ich habe für sie immer großen Respekt empfunden. Diese Entscheidung ist mir nicht leichtgefallen. Doch Baines Tod wird die Horde auseinanderreißen. Die Tauren werden das nicht akzeptieren. Und wenn sie gehen, werden andere ihnen folgen.\n\nWir müssen Baine retten. Nicht nur um seiner selbst willen, sondern auch für das Wohl der Horde. Ich kann nur hoffen, dass wir sie zur Vernunft bringen können, wenn wir wieder etwas mehr Zeit haben...\n\nIch habe Verbündete kontaktiert, die uns helfen werden. Ihr trefft sie in der Kluft der Schatten.", sourceObjective = "Trefft Euch mit Verbündeten in der Kluft der Schatten.", completion = "Es ist schön, Euch wiederzusehen, {name}. Wir müssen uns beeilen. Baine hat nicht mehr viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[55781] = { id = 55781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Verbündete", description = "Sylvanas Windläufer war einst meine Waldläufergeneralin. Jetzt ist sie mein Kriegshäuptling. Ich befolgte ihre Befehle in Krieg und Frieden.\n\nBis jetzt.\n\nBaine ist eine edle Seele. Seine Exekution würde einen Dolch tief in das Herz der Horde treiben.\n\nWir müssen ihn retten, {name}. Nur so können wir schützen, wer wir sind und woran wir glauben.\n\nIch habe nach Verbündeten gesandt, die Euch helfen werden. Denkt aber daran, dass Ihr Euch in Gefahr begebt, wenn Ihr an ihrer Seite kämpft.\n\nWenn Ihr meine Sicht teilt, dann trefft sie in der Kluft der Schatten. Viel Glück.", sourceObjective = "Trefft Euch mit Verbündeten in der Kluft der Schatten in Orgrimmar.", progress = "Wieder einmal sehen wir uns finsteren Zeiten gegenüber, {name}.", completion = "Eure Hilfe ist willkommen, {class}.\n\nBaine hat nicht mehr viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[55782] = { id = 55782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Richtern und Henkern", description = "Baine hat nicht mehr viel Zeit. Wir müssen jetzt handeln.", sourceObjective = "Schließt das Szenario \"Von Richtern und Henkern\" ab.", completion = "Zu schade, dass Bluthuf und der ganze Rest überlebt haben.\n\nAber diesen Ausgang hat unser Kriegshäuptling vorhergesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55783] = { id = 55783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Richtern und Henkern", description = "Als ich jünger war, habe ich begonnen, mit Baine Bluthuf Briefe auszutauschen. Durch unsere ungewöhnliche Freundschaft habe ich gelernt, dass die Horde durchaus edel sein kann.\n\nEr hat das beim Widerstand gegen Sylvanas bewiesen, als sie Derek Prachtmeer seines freien Willens berauben wollte. Diese edelmütige Tat kostet ihn nun sein Leben... wenn wir nicht eingreifen.\n\nWenn es in Azeroth Frieden geben soll, hängt unsere Hoffnung daran, dass gute Leute das Richtige tun. Leute wie Baine. Leute wie Ihr.\n\nBitte begleitet Jaina. Rettet meinen Freund und bringt ihn nach Hause.", sourceObjective = "Schließt das Szenario \"Von Richtern und Henkern\" ab.", completion = "Danke, dass Ihr uns bei der Rettung von Baine geholfen habt.\n\nDas war die richtige Entscheidung.", sourceObjectiveStatus = "unverified-source-field" }
quests[55784] = { id = 55784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleiches mit Gleichem", description = "{name}, König Anduin hat uns nach Sturmwind beordert.\n\nWir haben ihm Berichte über unsere Situation hier in Nazjatar geschickt, und er versteht das Ausmaß der Gefahr, der wir hier gegenüberstehen. Wenn er uns beide von der Frontlinie abzieht, muss es etwas sehr Wichtiges sein.\n\nWir treffen uns dann in Burg Sturmwind.", sourceObjective = "Trefft Euch mit Anduin Wrynn in Burg Sturmwind.", completion = "Wir befinden uns vielleicht im Krieg mit der Horde, aber das hat Baine nicht davon abgehalten, das Richtige zu tun.\n\nWir dürfen nicht weniger für ihn unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55785] = { id = 55785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Seesterne", description = "Unsere Späher haben Seesternschuppen als Tarnung verwendet. Das Problem ist, dass die Schuppen viel zu schnell zerfallen. Wir brauchen mehr Schuppen, wenn wir die Bewegungen der Naga im Blick behalten wollen.\n\nFalls Ihr zufällig auf Engelsschuppenseesterne stoßt, bringt sie bitte so bald wie möglich zum Rüstmeister.", sourceObjective = "Sammelt 5 Engelsschuppenseesterne.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55786] = { id = 55786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Seetang", description = "Wir haben so viele Verwundete und unser Bestand an Seetangbandagen ist gefährlich niedrig. Wenn Ihr klebrigen Seetang findet, bitte gebt ihn beim Rüstmeister ab.", sourceObjective = "Sammelt 5 Klumpen klebrigen Seetangs.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55787] = { id = 55787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Tangknospen", description = "Wir brauchen Rationen für unsere Truppen. Auch wenn Tangknospen nicht so gut schmecken wie andere Alternativen, so sind sie doch nahrhaft und in der Nähe von Tangwäldern reichlich vorhanden. Deshalb sind sie unsere erste Wahl als Rationen.\n\nFalls Ihr zufällig welche in Nazjatar findet, liefert sie bitte beim Rüstmeister ab. Am besten sind die, die gerade frisch vom Tang abgefallen sind.", sourceObjective = "Sammelt 5 abgefallene Tangknospen.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55789] = { id = 55789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Karpfen", description = "Unsere einheimischen Fischarten sind in Gefahr! Solltet Ihr einen Fisch an Land entdecken, bringt ihn bitte sofort in den nächsten See, Strom oder Fluss zurück. Arterhaltung ist jedermanns Pflicht!", sourceObjective = "Bringt 5 zappelnde Karpfen zurück ins Wasser.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55790] = { id = 55790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Tiefenkorallenknospen", description = "Für viele Spezies sind die Tiefenkorallenknospen an den hohen Säulen im Osten eine wichtige Nahrungsquelle, besonders für Tiefenrochen. Wir nutzen diese Knospen als Köder für Tiefenrochen, um sie als Reittiere zu fangen. Unsere Vorräte sind aber sehr gering. Wir werden also nicht die Luftunterstützung bieten können, die wir in Nazjatar brauchen werden.\n\nKönntet Ihr einige Tiefenkorallenknospen sammeln und sie beim Rüstmeister abgeben? Ihr werdet sicher dafür entlohnt.", sourceObjective = "Sammelt 5 Tiefenkorallenknospen.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55791] = { id = 55791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Ringelblatt", description = "Unsere Arzneimittelvorräte sind gefährlich niedrig. Solltet Ihr Ringelblatt finden, überlasst Eure Vorräte bitte dem Rüstmeister.\n\nIch sollte Euch warnen, dass Ringelblatt höchst giftig ist. Bitte geht vorsichtig damit um. Symptome einer Ringelblattvergiftung sind unter anderem Zornausbrüche, plötzliches Ansteigen der Körperkraft und impulsive Mordgedanken. Wenn Ihr dem Gift ausgesetzt wart, solltet Ihr die nächsten Naga aufsuchen und Eure mörderische Energie für einen guten Zweck einsetzen.", sourceObjective = "Sammelt 5 Stücke giftiges Ringelblatt.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55792] = { id = 55792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Kegelmuscheln", description = "Wenn wir uns gegen die Naga wappnen wollen, brauchen wir weit mehr Vorräte und Rüstzeug. Der größte Teil unserer Rüstungen und Waffen ist aus Kegelmuscheln gefertigt. Diese sind leicht, robust und kommen in dieser Region im Überfluss vor. Dennoch schrumpfen unsere Vorräte, und unsere Truppen brauchen Unterstützung.\n\nJeder, der undurchdringliche Kegelmuscheln bei sich hat, soll seine Vorräte beim Rüstmeister abgeben.", sourceObjective = "Sammelt 5 undurchdringliche Kegelmuscheln.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55793] = { id = 55793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Mehr Treibgut", description = "Ich habe im Sand im Westen Berge von Treibgut gesehen. Könntet Ihr mal nachsehen, ob sich in den Trümmern etwas Nützliches findet? Das könnte uns weiterhelfen. Seid aber gewarnt: Das ist ein Brutplatz der Hydras. Sie sind dort besonders aggressiv geworden, seit das Wasser zurückgegangen ist.\n\nSobald Ihr ein paar Vorräte gesammelt habt, könnt Ihr Euch beim Rüstmeister melden. Er wird Euch eine Belohnung geben.", sourceObjective = "Sammelt 5 Haufen Treibgut.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55794] = { id = 55794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgewinnungsturm" }
quests[55795] = { id = 55795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berg in Bewegung", description = "Ich habe eine solche Wucht erst einmal erlebt.\n\nIn Zeiten der Gefahr kann es vorkommen, dass Torcali ihre Kinder bittet, sie und ihre Schutzbefohlenen zu verteidigen.\n\nMöglicherweise hat sie Euer Tier zu sich gerufen. Geht zu ihr, um zu sehen, ob Ihr helfen könnt.", sourceObjective = "Sprecht mit Torcali.", completion = "<Torcalis Stimme dringt in Euren Geist ein.>\n\nIhr seid erneut meinem Ruf gefolgt, {name}. Wir dürfen keine Zeit verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55796] = { id = 55796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketzerei am Wegekreuz", description = "<Torcalis Stimme dringt in Euren Geist ein.>\n\nMeine Anhänger haben eine Pilgerschaft zu einem Ort namens Antul'Mitaplateau unternommen. Von den Gläubigen wird dieser Ort als das Wegekreuz von Zandalar angesehen. Dort befindet sich ein großer Wegschrein.\n\nIch spüre, dass sie einer großen Gefahr anheimgefallen sind.\n\nIch habe ihnen meine Kinder und meinen Champion, Jo'nok, zu Hilfe geschickt. Euer Schützling ist auch dabei. Geht zu ihr und sorgt dafür, dass meine Akolythen den Schrein sicher erreichen.\n\nEbnet ihnen mit aller Macht den Weg.", sourceObjective = "Trefft Euch mit Jo'nok am Antul'Mitaplateau in Nazmir.", completion = "Sie is' bereit. Ihr seid bereit. Die hab'n ganz sicher 'n Fehler gemacht, uns rauszufordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55797] = { id = 55797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut einer Mutter der Terrorhörner", description = "Die Gläubigen auf dem Weg zum Schrein werd'n beschützt.\n\nNehmt Eure Gefährtin un' zeigt ihnen die Wut einer Mutter der Terrorhörner.\n\nGlaubt an Eure junge Begleiterin. Sie hat schon immer gewusst, wie man kämpft.\n\nMacht den Weg frei. Tötet die Ketzer, die den Schrein von unsrem Loa besudeln.", sourceObjective = "Macht einen Weg zum großen Wegschrein am Antul'Mitaplateau frei.", completion = "Ihre Stärke zu erleb'n, is' 'ne Freude, {name}. Wir werd'n für unseren Glauben belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55798] = { id = 55798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie allein auf Reisen", description = "Sie is' hier. Ich kann spür'n, wie sie uns anschaut.\n\nMein Loa is' großzügig. Sie wird Euch für Eure Dienste belohn'.\n\nMöge die große Reisende Euch den Weg weisen, {name}.", sourceObjective = "Sprecht mit Torcali.", completion = "<Torcalis Stimme dringt in Euren Geist ein.>\n\nViele Male habe ich Euch gerufen und viele Male habt Ihr dem Ruf Folge geleistet.\n\nDie Kleine sagte mir, sie wolle Euch auf all Euren Wegen begleiten. Nach allem, was Ihr für meine Anhänger und meine Kinder getan habt, ist dies mein Geschenk an Euch.\n\nVon diesem Tag an bis zum Ende Eurer Tage werdet Ihr nie mehr allein reisen.\n\n<Torcali berührt Euren Kopf zärtlich mit ihrer riesigen Schnauze.>\n\nDanke und auf Wiedersehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55799] = { id = 55799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wendet sich", description = "Jetzt ist die Zeit, zuzuschlagen. Wir müssen die Kontrolle über Golganneths Gezeitenstein erlangen, und der Wurfspeer von Suramar ist unsere beste Chance, die ihn umgebende Barriere zu durchstoßen.\n\nJede Minute, die wir warten, ist eine weitere Minute, in der das Meer über uns hereinbrechen kann. Alles, was wir an Streitkräften zur Verfügung haben, bringt sich unten vor dem Lager in Stellung.\n\nZusätzlich zum Speer brauchen wir Eure Kraft, {name}. Wir haben nicht genug Truppen, um ihn allein zu sichern.", sourceObjective = "Greift das Nagalager an und übernehmt die Kontrolle über Golganneths Gezeitenstein.", completion = "Schnell, der Gezeitenstein!", sourceObjectiveStatus = "unverified-source-field" }
quests[55801] = { id = 55801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: Wir brauchen alles", description = "All unsere Vorräte gehen gefährlich schnell zuneige. Bitte geht und sammelt so viele Vorräte wie möglich.\n\nBitte kehrt mit allen Rohstoffen, die Ihr findet, zum Rüstmeister zurück!", sourceObjective = "Sammelt Rohstoffe überall in Nazjatar.", completion = "Habt Dank für Euren Beitrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[55813] = { id = 55813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohe Ziele", description = "Dieser Rabenschwarm, der Jagd auf die Bürger des Rostbolzens macht, ist unzumutbar!\n\nPrinz Erazmin hat mich gebeten, die Anzahl der Vögel zu reduzieren, aber ich könnte wirklich Eure Hilfe brauchen. Könnt Ihr mir helfen, einige davon zu töten?\n\nBenutzt mein Markierungsgewehr, wenn nötig. Ich nehme diejenigen ins Visier, die Ihr markiert, und helfe, sie vom Himmel zu holen.", sourceObjective = "Tötet 12 Rostschwingenraben.", completion = "Wir sind ein ausgezeichnetes Team.", sourceObjectiveStatus = "unverified-source-field" }
quests[55815] = { id = 55815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere Interessen", description = "Madame Goya interessiert sich für viele ungewöhnliche Gegenstände und nicht nur seltene Metalle.\n\nHaltet auf Euren Reisen in Nazjatar Ausschau nach diesen speziellen Gegenständen.\n\nBringt sie mir, dann wird Madame Goya in Betracht ziehen, Euch speziellen Zugang zu gewähren.", sourceObjective = "Bringt 5 besonders dichte Steine zum Stahlweisen Gao.", progress = "Habt Ihr die Gegenstände gefunden?", completion = "Ausgezeichnete Arbeit. Wir werden uns wieder sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55816] = { id = 55816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der andere Ort", description = "Während meiner Reisen in viele Zukunftsmöglichkeiten habe ich einen anderen Ort entdeckt, der dem Rostbolzen sehr ähnlich und doch ganz anders ist.\n\nIn dieser anderen Zeitlinie gibt es nur noch sehr wenig Lebendiges und stattdessen nur noch Maschinen.\n \nIhr müsst an diesen anderen Ort reisen. Ihr müsst die Speicherbanken der Aufziehgiganten scannen, die Ihr dort findet. Dann verwenden wir diese Daten, um sicherzustellen, dass unser Rostbolzen niemals wie dieser andere Ort wird.", sourceObjective = "Scannt 10 Aufziehgiganten.", completion = "Damit können wir vielleicht die Zeitlinie verändern, die uns alle an diesen Ort bringen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[55818] = { id = 55818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Naga", description = "Die Naga sind unsere wahren Feinde. Wir müssen sie stören, wo wir nur können. Alle anderen Vorhaben in Nazjatar sind diesem Ziel untergeordnet. Wenn Ihr unserer Sache helfen wollt, dann tötet einfach ein paar Feinde für uns. So verdient Ihr am schnellsten unseren Respekt.\n\nWenn Ihr Eure Aufgabe erledigt habt, geht zum Rüstmeister und holt Euch Eure Belohnung.", sourceObjective = "Tötet 15 Naga.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55819] = { id = 55819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Murlocs", description = "Murlocs sind meistens nur ein Störfaktor, aber einige Gruppierungen von ihnen entwickeln sich zu einer ernsthafteren Bedrohung für unsere Leute. Es ist an der Zeit, zusammenzuarbeiten und unsere Sicherheit zu gewährleisten, während wir uns durch Nazjatar bewegen.\n\nTötet einige der aggressiveren Murlocs und holt Euch beim Rüstmeister Eure Belohnung.", sourceObjective = "Tötet 15 Murlocs.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55820] = { id = 55820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Hydras", description = "Gegen die Hydras sind wir stark unterlegen. Sie sind wild, zäh und tödlich. Wir haben uns fast komplett aus der westlichen Region von Nazjatar zurückgezogen.\n\nWenn wir unsere Linien gegen die Naga halten wollen, müssen wir die westliche Region für unsere Streitkräfte sichern. Vernichtet so viele Hydras wie möglich und meldet Euch dann beim Rüstmeister.", sourceObjective = "Tötet 10 Hydras.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55821] = { id = 55821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Korallenurtume", description = "Korallenurtume erwachen langsam aus ihrem tiefen Schlaf. Ich muss Euch warnen. Das sind extrem gefährliche Kreaturen von enormer Größe und Kraft. Wenn noch mehr von ihnen erwachen, haben unsere Streitkräfte ein ernstes Problem.\n\nBesiegt einige dieser Urtume und holt Euch dann Eure Belohnung beim Rüstmeister.", sourceObjective = "Tötet 3 Korallenurtume.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55822] = { id = 55822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Makrura", description = "Die Makrura sind uns schon zu lang ein Dorn im Auge! Sie sind gegenüber beinahe allen anderen Spezies in Nazjatar aggressiv und sind besonders in Gruppen gefährlich. Wenn wir unsere Gewässer ein wenig von ihnen säubern, ist das sicher ein Vorteil für uns.\n\nMeldet Euch beim Rüstmeister, wenn Ihr fertig seid, um Eure Belohnung zu erhalten.", sourceObjective = "Tötet 10 Makrura.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55823] = { id = 55823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Krabben", description = "Die Krabbenpopulation nimmt in Nazjatar viel zu schnell zu und bedroht die heimischen Pflanzenarten. Dezimiert den Krabbenbestand für die Arterhaltung.\n\nMeldet Euch beim Rüstmeister, um Eure Belohnung zu erhalten.", sourceObjective = "Tötet 15 Krabben.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55824] = { id = 55824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Schnappdrachen", description = "Die Schnappdrachen sind eine der gefährlichsten Spezies in Nazjatar. Die Naga züchten sie wegen ihrer Boshaftigkeit und ihrer Fähigkeiten als Fährtenleser.\n\nWenn wir unsere Position weiter vor den Naga geheim halten wollen, müssen wir diese Rotten von Schnappdrachen sofort ausschalten.\n\nMeldet Euch beim Rüstmeister, wenn Ihr fertig seid, und holt Euch Eure Belohnung ab.", sourceObjective = "Tötet 10 Schnappdrachen.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55825] = { id = 55825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Ein paar Tiefenrochen", description = "Die Tiefenrochen fressen sämtliche Korallenknospen östlich von hier. Wenn wir ihre Population nicht eindämmen, könnte es zu einer ökologischen Katastrophe kommen.\n\nNachdem Ihr das erledigt habt, meldet Euch beim Rüstmeister für eine Belohnung.", sourceObjective = "Tötet 10 Tiefenrochen.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55827] = { id = 55827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Naga", description = "Die Naga sind unsere wahren Feinde. Wir müssen sie stören, wo wir nur können. Alle anderen Vorhaben in Nazjatar sind diesem Ziel untergeordnet. Wenn Ihr unserer Sache helfen wollt, dann tötet einfach ein paar Feinde für uns. So verdient Ihr am schnellsten unseren Respekt.\n\nWenn Ihr Eure Aufgabe erledigt habt, geht zum Rüstmeister und holt Euch Eure Belohnung.", sourceObjective = "Tötet 25 Naga.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55828] = { id = 55828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Murlocs", description = "Murlocs sind meistens nur ein Störfaktor, aber einige Gruppierungen von ihnen entwickeln sich zu einer ernsthafteren Bedrohung für unsere Leute. Es ist an der Zeit, zusammenzuarbeiten und unsere Sicherheit zu gewährleisten, während wir uns durch Nazjatar bewegen.\n\nTötet einige der aggressiveren Murlocs und holt Euch beim Rüstmeister Eure Belohnung.", sourceObjective = "Tötet 25 Murlocs.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55829] = { id = 55829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Hydras", description = "Gegen die Hydras sind wir stark unterlegen. Sie sind wild, zäh und tödlich. Wir haben uns fast komplett aus der westlichen Region von Nazjatar zurückgezogen.\n\nWenn wir unsere Linien gegen die Naga halten wollen, müssen wir die westliche Region für unsere Streitkräfte sichern. Vernichtet so viele Hydras wie möglich und meldet Euch dann beim Rüstmeister.", sourceObjective = "Tötet 15 Hydras.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55830] = { id = 55830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Korallenurtume", description = "Korallenurtume erwachen langsam aus ihrem tiefen Schlaf. Ich muss Euch warnen. Das sind extrem gefährliche Kreaturen von enormer Größe und Kraft. Wenn noch mehr von ihnen erwachen, haben unsere Streitkräfte ein ernstes Problem.\n\nBesiegt einige dieser Urtume und holt Euch dann Eure Belohnung beim Rüstmeister.", sourceObjective = "Tötet 7 Korallenurtume.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55831] = { id = 55831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Makrura", description = "Die Makrura sind uns schon zu lang ein Dorn im Auge! Sie sind gegenüber beinahe allen anderen Spezies in Nazjatar aggressiv und sind besonders in Gruppen gefährlich. Wenn wir unsere Gewässer ein wenig von ihnen säubern, ist das sicher ein Vorteil für uns.\n\nMeldet Euch beim Rüstmeister, wenn Ihr fertig seid, um Eure Belohnung zu erhalten.", sourceObjective = "Tötet 15 Makrura.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
