quests[55833] = { id = 55833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Schnappdrachen", description = "Die Schnappdrachen sind eine der gefährlichsten Spezies in Nazjatar. Die Naga züchten sie wegen ihrer Boshaftigkeit und ihrer Fähigkeiten als Fährtenleser.\n\nWenn wir unsere Position weiter vor den Naga geheim halten wollen, müssen wir diese Rotten von Schnappdrachen sofort ausschalten.\n\nMeldet Euch beim Rüstmeister, wenn Ihr fertig seid, und holt Euch Eure Belohnung ab.", sourceObjective = "Tötet 15 Schnappdrachen.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55834] = { id = 55834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Mehr Tiefenrochen", description = "Die Tiefenrochen fressen sämtliche Korallenknospen östlich von hier. Wenn wir ihre Population nicht eindämmen, könnte es zu einer ökologischen Katastrophe kommen.\n\nNachdem Ihr das erledigt habt, meldet Euch beim Rüstmeister für eine Belohnung.", sourceObjective = "Tötet 15 Tiefenrochen.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55836] = { id = 55836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Elitenaga", description = "Bekämpft die Elitetruppen der Naga in Nazjatar. Sobald wir einige ihrer Anführer getötet haben, können sich unsere Leute wieder freier bewegen.\n\nMeldet Euch beim Rüstmeister für eine Belohnung.", sourceObjective = "Tötet 5 Elitenaga.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55837] = { id = 55837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Gefährliche Kreaturen", description = "In Nazjatar gibt es viele Kreaturen, die wesentlich gefährlicher sind als andere ihrer Art. Ich überlasse es Euch, sie zu finden und zu besiegen.\n\nWenn Ihr Eure Arbeit erledigt habt, dann meldet Euch beim Rüstmeister für eine Belohnung.", sourceObjective = "Tötet 1 seltene Kreatur in Nazjatar.", progress = "Ich weiß, es ist schmutzige Arbeit, aber jemand muss sie ja machen.", completion = "Das wird uns unsere Vorhaben in Nazjatar erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55845] = { id = 55845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne", description = "<Die Angriffspläne sind mit fluoreszierendem Tintenfischblau auf das Pergament geschrieben und mit Azsharas Siegel versehen.>\n\nBefehle der Königin:\n\nKönigin Azshara hat befohlen, dass sich die gesamten Nagastreitkräfte auf einen Großangriff auf die Eindringlinge der Allianz in unserem Land vorbereiten sollen. Die genauen Angriffspläne wurden bereits an die verschiedenen Einheitenkommandanten weitergegeben.\n\nDie Allianz soll vor der Macht unserer Königin erzittern!", sourceObjective = "Besorgt 8 Angriffspläne.", progress = "Welche Neuigkeiten bringt Ihr von der Front?", completion = "Ausgezeichnete Arbeit, {class}. Ihr habt der Allianz einen großen Dienst erwiesen. Jetzt, wo wir die Angriffspläne besitzen, können wir unsere Verteidigung schon vor dem Angriff aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55846] = { id = 55846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Rituale", description = "Die Naga nutzen dunkle, verbotene Rituale, um die Elemente ihrem Willen zu unterwerfen.\n\nSolche Rituale bedrohen jedoch das Gleichgewicht der Elemente, das unsere Welt zusammenhält. Diese Rituale müssen aufhören. \n\nZum Glück sind diese Vorgänge zu kompliziert, als dass die Naga sie aus dem Gedächtnis ausführen könnten. Die Anleitungen zu diesen Ritualen finden sich in uralten Texten.\n\nWenn wir die uralten Folianten zerstören, die die Rituale enthalten, wird dieses Wissen für die Naga für immer verloren sein.\n\nHolt die Folianten und ich kümmere mich um deren Zerstörung.", sourceObjective = "Besorgt 8 Folianten der Bindung.", progress = "Habt Ihr die Folianten?", completion = "Ich werde mich darum kümmern, dass die Folianten der Bindung sofort zerstört werden. Möge Neptulon Euch auf Eurem Weg leiten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55849] = { id = 55849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgewinnungsturm" }
quests[55851] = { id = 55851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenzielle Ermächtigung", description = "Champion, aufregende Neuigkeiten!\n\nIch weiß, dass Ihr im Moment gut mit der Nagabedrohung beschäftigt seid, aber wir brauchen Euch in der Herzkammer! MUTTER hat endlich ihre Berechnungen abgeschlossen und sie hat einen Plan, was wir als Nächstes machen sollen!\n\nKommt so schnell Ihr könnt nach Silithus. Azeroth braucht Euch!", sourceObjective = "Trefft Magni in der reparierten Herzkammer in Silithus.", progress = "Ah, da seid Ihr ja. Die Kammer sieht schon besser aus, oder?", completion = "Willkommen zurück, Champion! Jetzt, da MUTTER mit ihren Berechnungen fertig ist, gibt es eine Menge zu tun.\n\nLegen wir los, okay?", sourceObjectiveStatus = "unverified-source-field" }
quests[55860] = { id = 55860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquidierung von Seeschnecken", description = "Meine kurzen Forschungen haben ergeben, dass bei dem Verfeinerungsprozess ein Nebenprodukt entsteht, das mit bloßem Auge nicht erkennbar ist, aber mit gebrochenem, biolumineszentem Licht sichtbar gemacht werden kann. \n\nDer Meeresgrund ist voller Kreaturen, die genau das erzeugen, was wir zum Aufspüren dieses Waffenverstecks brauchen.", sourceObjective = "Sammelt 8 biolumineszenten Schleim von leuchtenden Seeschnecken im Blutflossendorf.", progress = "Habt Ihr den Schleim?", completion = "Die Substanz ist klebriger als erwartet, sollte aber dennoch ihren Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55861] = { id = 55861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst Euch von den Rückständen leiten", description = "Ich habe ein Gerät gebaut, das nach dem Einschalten biolumineszentes Licht abgibt und somit Azeritrückstände sichtbar machen kann.\n\nDadurch solltet Ihr eine deutliche Spur zu dem Waffenversteck erhalten.\n\nViel Glück, {name}.", sourceObjective = "Folgt der Spur der Rückstände, um die Azeritwaffentruhe zu finden.", completion = "<Obwohl sie fest verschlossen ist, lassen die abstrahlende Energie und das Gewicht erahnen, dass die Truhe Azeritwaffen enthält.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55862] = { id = 55862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkenntnisse über unsere Feinde", description = "Wir wissen nicht, was uns in diesem Land erwartet. Wir können nicht weitermarschieren, ohne zu wissen, was sie gegen uns auffahren werden.\n\nObwohl unsere neuen Verbündeten schon viel Leid von den Naga erfahren haben, wird ihr Schmerz nicht umsonst gewesen sein.\n\nDie Kelfinnen sollten wertvolles Wissen über die Streitkräfte der Naga besitzen.\n\nMit ihrer Hilfe können wir vielleicht mehr darüber herausfinden, wie unsere Gegner organisiert sind.\n\nSprecht mit Neri und findet heraus, was sie weiß und wie sie uns helfen kann.", sourceObjective = "Sprecht mit Neri, um mehr über die Naga in Nazjatar zu erfahren.", completion = "Ihr wollt etwas über die Naga erfahren?\n\nIch kann Euch erzählen, was ich weiß, aber die Kelfinnen, die immer noch gefangen gehalten werden, können Euch aus erster Hand berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55863] = { id = 55863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissensverfall", description = "Die Kelfinnen sind nicht das erste Mal Azsharas Grausamkeit ausgesetzt. \n\nSie befehligt die Kreaturen der Finsternis, die meinesgleichen gefangensetzen und ihren Geist durcheinanderbringen. Sie nagen an ihren Erinnerungen, bis nur noch ein leere Hülle übrig bleibt. \n\nWenn Ihr sie bald erreicht, sind sie vielleicht noch in einem Zustand, dass sich ihre Rettung lohnt.", sourceObjective = "Rettet Fenn, Kono und Esma aus den Klauen der willenszerstörenden Zoatroiden.", completion = "Ich dachte, ich würde in dieser Höhle sterben. Manchmal habe ich mir das auch gewünscht. \n\nIch danke Euch, dass Ihr mich da rausgeholt habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55864] = { id = 55864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis ist der Tod", description = "Wir haben lange geglaubt, dass das Meer groß genug für alle ist, die es ihr Zuhause nennen wollen. \n\nLeider scheinen die Naga das nicht so zu sehen. \n\nSie töten und entführen unsere Spezies gnadenlos und es wird Zeit, dass sie dafür bezahlen.", sourceObjective = "Tötet 10 Naga in der Zanj'irbrandung und im Tiefseesklavenpferch.", completion = "Wenn sie tot sind, können sie mir kein Leid mehr zufügen.\n\nWenn ich mir das lange genug einrede, werde ich es vielleicht irgendwann glauben, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[55865] = { id = 55865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir über die Naga wissen", description = "Es ist schön, wieder ich selbst zu sein. Das habe ich Euch zu verdanken.\n\nIch habe immer noch Kopfschmerzen vom Einfluss der Zoatroiden, aber ich glaube, den anderen geht es noch schlimmer.\n\nVersorgt ihre Wunden mit dieser Salbe und ich werde Euch alles über die Naga erzählen, was ich weiß.", sourceObjective = "Kümmert Euch um die Wunden der Kelfinne und hört Euch an, was Fenn über die Naga weiß.", progress = "Ihr stört.", completion = "Was auch immer in der Festung verborgen ist, es muss zerstört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55866] = { id = 55866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundungen im Geheimen", description = "Allein in die Festung zu gehen wäre Selbstmord.\n\nDie Zanj'ir töten Unbekannte sofort.\n\nDie einzige Möglichkeit, hineinzukommen, ohne dabei zu sterben, ist unter dem Einfluss eines Zoatroiden hineinzugehen.\n\nDie willenlosen Sklaven werden direkt zur Arbeit geschickt.\n\nIhr müsst allen Aufforderungen Folge leisten, oder sie werden bemerken, dass Ihr noch bei klarem Verstand seid.\n\nSobald die Zanj'ir glauben, dass Ihr willenlos seid, sollte es einfacher sein, sich unauffällig in ihrem Territorium zu bewegen und ihr Geheimnis zu lüften.", sourceObjective = "Späht die Terrasse der Zanj'ir aus, während Ihr vorgebt, gedankengefesselt zu sein.", completion = "Was nützt Ihr uns, wenn Ihr nicht arbeitet?", sourceObjectiveStatus = "unverified-source-field" }
quests[55867] = { id = 55867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begehrte Kristalle", description = "Die Waffentruhe zu finden, dürfte kein Problem sein, wenn wir erst die richtigen Hilfsmittel haben. Wir brauchen nur ein bisschen Licht und eine Menge biolumineszente Flüssigkeit!\n\nDas scheint alles recht einfach zu sein, oder? Aber der Schlüssel ist der lichtbrechende Tiefseekristall.\n\nMan sagt, dass der Stamm der Blutflossen ganz versessen auf diese Kristalle ist, also dürfte es Euch nicht allzu viele Schwierigkeiten bereiten, einen zu bekommen.", sourceObjective = "Holt einen Tiefseekristall von Horter Moarrgl.", progress = "Habt Ihr den Kristall gefunden?", completion = "Die Reinheit dieses Kristalls ist wirklich bemerkenswert, findet Ihr nicht? Ich glaube, der wird seinen Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55868] = { id = 55868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst Euch von den Rückständen leiten", description = "Ich habe ein Gerät gebaut, das nach dem Einschalten biolumineszentes Licht abgibt und so Azeritrückstände sichtbar machen kann.\n\nDadurch solltet Ihr eine deutliche Spur zu dem Waffenversteck erhalten.\n\nViel Glück, {name}.", sourceObjective = "Folgt der Spur der Rückstände, um die Azeritwaffentruhe zu finden.", completion = "<Obwohl sie fest verschlossen ist, lassen die abstrahlende Energie und das Gewicht erahnen, dass die Truhe Azeritwaffen enthält.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55869] = { id = 55869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteck ausräumen", description = "<Während der Untersuchung der Kiste ist Lärm in der Höhle zu hören: eine vertraute Stimme, die Befehle ruft.>", sourceObjective = "Kümmert Euch um Priscilla Aschenwind und ihre Diener.", completion = "Offenbar reicht Azsharas Einfluss weiter, als wir gedacht haben. \n\nAschenwind mag entkommen sein, aber wenigstens haben wir die Waffen gesichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[55870] = { id = 55870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquidierung von Seeschnecken", description = "Bei dem Verfeinerungsprozess von Azerit entsteht ein Nebenprodukt, das mit bloßem Auge nicht erkennbar ist, aber mit gebrochenem, biolumineszentem Licht sichtbar gemacht werden kann. \n\nDer Meeresgrund ist voller Kreaturen, die genau das erzeugen, was wir zum Aufspüren dieses Waffenverstecks brauchen.", sourceObjective = "Sammelt 8 biolumineszenten Schleim von leuchtenden Seeschnecken im Blutflossendorf.", progress = "Habt Ihr den Schleim?", completion = "Das ist klebriger als erwartet, sollte aber dennoch seinen Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55871] = { id = 55871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde sammeln", description = "Draußen ist es gefährlich.\n\nIn der Kelfinnengrotte ist es sicher. \n\nWir finden verirrte Krabben und Schnecken und andere Freunde.\n\nHier bekommen sie einen neuen Namen und ein neues Zuhause. \n\nFindet Freunde wie diese und bringt sie nach Hause.", sourceObjective = "Sammelt Sandscherenkrabben und Schlickkriecher für Narm.", progress = "Habt Ihr uns Freunde mitgebracht?", completion = "Sie sind bereits meine Freunde. Jetzt sind sie sicher.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55872] = { id = 55872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sie sich verstecken", description = "Diese tückischen Schlangen haben angefangen, Assassinen zu entsenden.\n\nSie verstecken sich in der Nähe und töten alle, die sie nicht in die Sklavenpferche mitnehmen können.\n\nSogar die Schwämme wollen sie loswerden!\n\nDie Sporen werden die verräterischen Naga offenbaren... und dann könnt Ihr sie töten.\n\nWir müssen unser Volk beschützen!", sourceObjective = "Benutzt den frischen Schwamm, um 5 Assassinen der Zanj'ir aufzuspüren und zu töten.", completion = "Ha! Sie hassen diese Dinger.\n\nSehr schön zerstört.", sourceObjectiveStatus = "unverified-source-field" }
quests[55873] = { id = 55873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kritch töten", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr.\n\n<Rlgmrr hüpft verängstigt herum und zeigt auf die Höhle.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<Er macht ein beängstigendes Gesicht und Schnappbewegungen mit seinen Händen.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", sourceObjective = "Tötet den Kritch.", completion = "Llrmmrgl! Mrgggl mrgl!\n\n<Rlgmrr lacht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55874] = { id = 55874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Wir werden jeden Moment einen Geysirausbruch erleben.\n\nDie Auswirkungen des Gezeitensteins sind weitreichend.\n\nWir müssen tun, was wir können, um weitere Zerstörungen zu verhindern.\n\nBenutzt diese Dichtungsmasse, um die nächsten Eruptionen zu unterdrücken!", sourceObjective = "Versiegelt alle instabilen Geysire.", completion = "Hat's euch erwischt? Ich hatte das Gefühl, Ihr seid getroffen worden.\n\nPassiert den Besten von uns! Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[55875] = { id = 55875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Behaltet hier alles im Blick... jeden Moment jetzt...\n\nSobald diese Geysire ausbrechen, geht hinein und versiegelt sie.\n\nJe mehr sie beben, desto mehr bricht auseinander!\n\nWir müssen diese Dinger unter Kontrolle bringen.", sourceObjective = "Versiegelt alle instabilen Geysire.", completion = "Gute Arbeit!\n\nIch hatte auf etwas Hilfe von den Riffwanderern gehofft, aber man nimmt, was man kriegen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[55876] = { id = 55876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Erdbeben! Schlangen! Wasser, das aus jeder Richtung kommt.\n\nWas ist hier eigentlich los?\n\nNeri sagte, wir sollen einige Löcher in der Verteidigung stopfen... Ich hätte nicht gedacht, dass sie das wörtlich meint.\n\nNehmt etwas von diesem Schleim und stopft bei der nächsten Eruption etwas davon in das Loch.", sourceObjective = "Versiegelt alle instabilen Geysire.", completion = "Jawoll! Das war doch mal eine wasserdichte Heldentat!", sourceObjectiveStatus = "unverified-source-field" }
quests[55877] = { id = 55877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Wir haben immer ein Auge auf die instabilen Geysire.\n\nSeit das Wasser weg ist, versucht das Meer, einen Weg zurück zu finden.\n\nWenn wir überall Ausbrüche zulassen, könnten wir bald dem Untergang geweiht sein!\n\nHelft mir, diese hier zu verstopfen!\n\nSeid aber vorsichtig, ich habe am eigenen Leib erfahren, dass die einen ganz schönen Bumms haben.", sourceObjective = "Versiegelt alle instabilen Geysire.", completion = "Das Glück des Ozeans war mit uns! Gut gemacht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55878] = { id = 55878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geysire stopfen", description = "Habt Ihr von den Geysiren gehört?\n\nÜberall in den kürzlich trockengelegten Gebieten versucht das Wasser, alles wieder aufzufüllen, wo es weggezogen wurde.\n\nDas Meer ist wütend. Ich glaube, es mag Azshara auch nicht.\n\nWir werden hier immer wieder alles dichtmachen müssen, bis wir eine endgültige Lösung gefunden haben.", sourceObjective = "Versiegelt alle instabilen Geysire.", completion = "Vielen Dank.\n\nIch habe so ein Gefühl, als ob das nicht lange halten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[55879] = { id = 55879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt auf dem wissenschaftlich verbesserten Eber", description = "Wir wissen nicht, wie lange die Größenänderung anhalten wird, also los.\n\nWir werden auf diesem Rieseneber reiten, um die Armee der Untoten zwischen uns und Henry niederzumähen.\n\nDie großen von ihnen pulsieren vor dunkler Magie. Ich wette, wenn wir sie töten, werden auch alle Feinde um sie herum ausgelöscht.\n\nHenry wird hoffentlich mehr darüber wissen, was die Oger geplant haben.", sourceObjective = "Reitet auf dem riesigen Eber, um die Armee der Untoten zu vernichten.", progress = "Bitte... helft mir! Ich halte das nicht mehr lange aus!", completion = "Ich danke Euch, Fremdling. Ich dachte schon, ich müsste dafür büßen, dass ich meine Freunde nicht retten konnte.\n\nMein Irrtum ist eine große Erleichterung.", sourceObjectiveStatus = "unverified-source-field" }
quests[55880] = { id = 55880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieumleitung", description = "Willkommen zurück, mein liebes Versuchsobjekt.\n\nWas steht heute auf dem Plan...\n\n<Pristy blättert durch einige Notizen und lächelt.>\n\n...Mein Lieblingsprojekt, der NRG-100!\n\nIch bin sehr zufrieden mit den potentiellen Verbesserungen, die ich bei Effizienz, Kraft und Zerstörungskraft erreicht habe.\n\nDazu musste ich lediglich ein bisschen Stabilität opfern!\n\nLegt den NRG-100 an, sobald Ihr bereit seid.", sourceObjective = "Benutzt den NRG-100, um 6 Energiezellen aufzuladen.", progress = "Experimentierfreudig", completion = "Erstaunlicher Test, liebes Versuchsobjekt!\n\nIch werde am NRG-100 noch weitere Veränderungen vornehmen, die auf diesen Ergebnissen basieren. In ein paar Tagen bin ich bereit für Folgetests.", sourceObjectiveStatus = "unverified-source-field" }
quests[55881] = { id = 55881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemläuterung", description = "Überall in diesem Gebiet sind die Totems der Harpyien verteilt.\n\nHarpyien sind dafür bekannt, dass sie die Wesen in ihrer Nähe mit ihren Totems verderben. Ich kann sogar jetzt ihr elendes Flüstern vernehmen...\n\nWir müssen die Totems vernichten, bevor unsere Leute ihrer düsteren Magie erliegen!", sourceObjective = "Zündet 5 Harpyientotems an.", completion = "Die bösartige Magie an diesem Ort löst sich auf. Ich glaube, vorerst sind wir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[55882] = { id = 55882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an die Basis", description = "Wir haben es geschafft! Wir sind einen Schritt näher daran, diese Insel zu verlassen.\n\nKehren wir zum Lager zurück und berichten der Kapitänin von unserem Erfolg.", sourceObjective = "Kehrt zum Allianzlager zurück und sprecht mit Kapitänin Garrick.", completion = "Es erleichtert mich, dass Ihr Meredy retten konntet. Ein weiteres Leben gerettet und eines weniger geopfert.\n\nUnd gut, dass Henry dank Euch wieder ganz der Alte ist.\n\nWir werden mit Meredy zusammen einen schlagkräftigen Plan schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55883] = { id = 55883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ein Rochen durch die Lüfte", description = "Ich würde gerne die Eier der Tiefenrochen finden, bevor sie ausschlüpfen, damit wir eine Bindung zu ihnen aufbauen können.\n\nImmerhin können wir dann, wenn wir schon nicht schwimmen können, wenigstens fliegen!\n\nBringt mir für den Anfang ein paar neue Eier für das neue Projekt. Wir nennen es Rochenreiter!", sourceObjective = "Holt 7 Tiefenrocheneier zurück.", progress = "Habt Ihr viele Eier gefunden?", completion = "Ah! Perfekt! Bald werden wir den Wind spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[55884] = { id = 55884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinnsverseuchung" }
quests[55885] = { id = 55885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ricos Rettung", description = "Einige unserer Raunacken werden vermisst. Ich habe versucht, sie zu finden, aber das Ungeziefer hat mich hier festgenagelt! \n\nIch könnte wirklich Eure Hilfe brauchen, {name}. Versucht, meine verschollenen Soldaten zu retten.", sourceObjective = "Rettet die Soldaten Levy, Katrin und Bybee.", completion = "Rico hat ein gutes Wort für Euch eingelegt. Das könnte vielleicht zu einer Beförderung führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55886] = { id = 55886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Metzler der Zanj'ir" }
quests[55887] = { id = 55887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Donnerpfeil Alzana" }
quests[55888] = { id = 55888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Eisspeer Qalina" }
quests[55889] = { id = 55889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Kyx'zhul der Tiefensprecher" }
