quests[55901] = { id = 55901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenwiderstand", description = "Unterstützt den Rostbolzenwiderstand." }
quests[55905] = { id = 55905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschleppungsverhinderung", description = "Hier sind ENTFÜHRUNGEN im Gange, {name}!\n\nIch schwöre bei Gold, fliegende Roboter stoßen auf die Stadt herunter und schnappen sich die Leute wie bei Gallywix' Buffet kurz vor Ladenschluss!\n\nZum Glück für den Rostbolzenwiderstand hat Gazlowe mich mit meinen Sprengladungen hergerufen, um die Lage zu retten.\n\nWollt Ihr mitmachen? Nehmt einen meiner Raketenwerfer und schießt diese Sicherungskisten vom Himmel.\n\nWas immer sich darin befindet, wird ziemlich schnell herunterfallen, also müsst Ihr darunterlaufen und es auffangen.", sourceObjective = "Befreit 6 gefangene Mechagnome und fangt sie, bevor sie auf dem Boden aufschlagen.", completion = "Gut geschossen!\n\nUnd übrigens, macht Euch keine Sorgen, falls Ihr \"zufällig\" einen Mechagnom oder zwei verfehlt habt... Ist mir auch schon passiert!\n\n<Penny zwinkert Euch zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55937] = { id = 55937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versteck ausräumen", description = "<Während der Untersuchung der Kiste ist Lärm in der Höhle zu hören: eine vertraute Stimme, die Befehle ruft.>", sourceObjective = "Kümmert Euch um Priscilla Aschenwind und ihre Diener.", completion = "Offenbar reicht Azsharas Einfluss weiter, als wir gedacht haben. \n\nAschenwind mag entkommen sein, aber wenigstens haben wir die Waffen gesichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[55965] = { id = 55965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westwärts", description = "Kapitänin Garrick sendet uns aus, im Westen nach den anderen Expeditionsmitgliedern zu suchen.\n\nAlaria und ich werden vorausgehen. Trefft uns im Westen, dann werden wir sehen, was wir finden können.", sourceObjective = "Trefft Björn Krafthand westlich des Allianzlagers.", completion = "Eine riesige Spinnengrube direkt vorm Lager! Sind wir nicht echte Glückspilze?", sourceObjectiveStatus = "unverified-source-field" }
quests[55967] = { id = 55967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensättigen leicht gemacht", description = "Es wird Zeit, dass die Schnappdrachen gefüttert werden, aber das überlässt man lieber jemandem, den man nicht mehr unbedingt braucht.\n\nDie Biester fressen alles, sogar Euren Arm, wenn Ihr ihn nicht schnell genug wegzieht.\n\nZum Glück für Euch sind sie auf den Geschmack von Zitterstachelrogen gekommen.", sourceObjective = "Sammelt Zitterstachelrogen und füttert die wilden Schnappdrachen damit.", completion = "Ich bin überrascht, dass sie Euch nicht verspeist haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55970] = { id = 55970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermürbungstaktik" }
quests[55973] = { id = 55973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefennatternexperimente" }
quests[55976] = { id = 55976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von den Ankoanern der Meeresklinge", description = "Die Ankoaner der Meeresklinge schätzen all Eure Hilfe.\n\nBitte nehmt diese Vorräte als ein Zeichen unserer Dankbarkeit und ein Versprechen auf mehr, solltet Ihr uns auch weiterhin unterstützen.", sourceObjective = "Sprecht mit Sprecher Utia in Mezzameer über Eure Belohnung.", completion = "Durch Eure Anstrengungen gegen die Naga konnte unser Klan weitere Ressourcen auf dem Schlachtfeld sicherstellen. Bitte nehmt diese Vorräte als Geschenk an, {name}.\n\nJe deutlicher Ihr das Schlachtfeld beherrscht, desto mehr Ressourcen können wir erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55979] = { id = 55979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederholung ist der Schlüssel", description = "Ihr habt mir nicht alles gesagt!\n\nDa dachte ich, wir wären jetzt Freunde und doch habt Ihr mir Euren großartigen Schraubenschlüssel vorenthalten!\n\n<Christy begutachtet ihn eingehend.>\n\nNun, nicht allzu großartig... Ich erkenne den Üb3r-Schrauber von den Bauplänen, aber wer immer den gebaut hat, dem fehlt es an gewissen Handwerksfähigkeiten.\n\nIch werde ihn für Euch verbessern. Bringt mir einen überladenen Mechakern von einem Mechanokrabbler.\n\nKeine Ausreden. Ich werde Eure Fehler korrigieren.", sourceObjective = "Holt einen überladenen Mechakern von dem überladenen Mechanokrabbler.", progress = "Einen Üb3r-Schrauber ohne überladenen Mechakern herzustellen... Ha! Das muss man sich mal vorstellen.", completion = "Das wird nur eine Minute dauern. Seht gut hin, was ich mache, und Ihr werdet das eine oder andere lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55980] = { id = 55980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Schuppe gespuckt", description = "Ich habe versucht, einige Schuppen von jungen Hydras in der Nähe zu sammeln. \n\nIhre Biegsamkeit und Stärke macht sie unglaublich vielseitig.\n\nBei all den übellaunigen, alten Hydras, die hier herumtrampeln, habe ich keine großen Chancen.\n\nKönnt Ihr mir welche besorgen?", sourceObjective = "Sammelt 20 Hydraschuppen von Hydras in der Nähe.", progress = "Habt Ihr genug?", completion = "Ich hätte gedacht, dass Ihr mit diesen Landstampfern langsamer seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[55981] = { id = 55981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau vor ihren Nasen", description = "Wir müssen in die Finsterbrecherzitadelle, die Kapitänin der Expedition retten und den Oger beseitigen, der hinter alldem steckt.\n\nMeredy wird eine Illusion erschaffen, damit Ihr wie ein Oger ausseht, und Ihr bringt uns als \"Gefangene\" in die Zitadelle.\n\nIch werde in der Zwischenzeit meine Bemühungen verbergen, die Schattenmagie zu unterdrücken.\n\nSprecht mit Meredy, wenn Ihr für den Zauber bereit seid.\n\nIhre Illusion sollte nur von vorübergehender Dauer sein, solange sie ihn richtig wirkt.", sourceObjective = "Lasst Euch von Meredy in einen Oger verwandeln und späht die nahe gelegene Ogerzitadelle aus.", completion = "Bald werden wir all dem hier ein Ende gesetzt haben. Wir müssen nur noch ein wenig länger durchhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55982] = { id = 55982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herren des Wassers" }
quests[55983] = { id = 55983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sicherer Ort", description = "<Der Murloc sieht ziemlich mitgenommen aus. Vielleicht ist er bei Euren Freunden in Mezzameer besser aufgehoben.>", sourceObjective = "Begleitet Mrrl zurück nach Mezzameer.", completion = "<Mrrl scheint sich in seinem neuen Zuhause wohlzufühlen, und seine Familie hat hier ebenfalls Zuflucht gesucht. Es ist unwahrscheinlich, dass Ihr diese neue Murlocplage beseitigen könnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55984] = { id = 55984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gute Offensive", description = "Korl soll die Naga beobachten, also macht er das auch.\n\nSie sind böse, wisst Ihr... Wirklich... schreckliche, furchtbare Monster.\n\nIch glaube, ich kann nicht mehr einfach zusehen.\n\nWas ist gleich noch mal die beste Verteidigung?\n\nHelft mir, ihnen zu zeigen, dass man zermatscht wird, wenn man böse Sachen macht!", sourceObjective = "Tötet 50 Naga.", completion = "Das war mein schönster Tag. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[55985] = { id = 55985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderes Funkeln", description = "In den Becken dort unten gibt es einige kleine, hübsche Perlen. \n\nSie wurden im Verlauf irgendeines Azsh'arirituals dort hineingeworfen. \n\nHaben sie eine Bedeutung? Ich weiß es nicht. Aber ich hätte gern ein paar von ihnen. \n\nSeid ein netter Schwerfuß und besorgt mir ein paar davon, bitte!", sourceObjective = "Sammelt 10 magiegetränkte Perlen.", progress = "Habt Ihr alle Perlen gefunden?", completion = "Ich kann ihr Leuchten spüren! Es kribbelt auf meiner Hand und reicht bis in den Meeresboden.\n\nSehr hübsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[55986] = { id = 55986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ei der Daus", description = "Diese Kammer ist gleichermaßen wunderschön und beängstigend.\n\nWas hier geboren wird, wird so viele Leben ruinieren.\n\nWir können den Kapseln keinen Schaden zufügen, aber wir können die Eier der Schlangen, die sie bewachen, einfach vernichten.\n\nZerstört die Eier, jedes einzelne hilft.\n\nArme Eier...", sourceObjective = "Vernichtet 10 Tiefennatterneier.", completion = "Je weniger der unheimlichen, fliegenden Schlangen die Naga bewachen, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[55988] = { id = 55988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Oger zur Schlachtbank", description = "Das ist schrecklich, {name}. Kapitänin Kelra ist durch Magie gebunden, die Oger machen sich bereit, unsere Freunde anzugreifen, und das Ritual ist fast abgeschlossen!\n\nIch muss ruhig bleiben. Wir dürfen jetzt nicht aufgeben.\n\nEs klingt vielleicht ein wenig riskant, aber wir müssen die Oger angreifen.\n\nWir sind hier hinter den feindlichen Linien, also sollten wir sie überraschen und vom Lager ablenken können.\n\nSchaltet alle Oger aus, die Ihr finden könnt. Das sollte sie von unseren Freunden fernhalten.", sourceObjective = "Tötet 8 Oger in der Finsterbrecherzitadelle.", completion = "Das sollte uns genug Zeit verschaffen, um das Ritual aufzuhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[55989] = { id = 55989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katapultsprengung", description = "Habt Ihr die Katapulte auf unserem Weg bemerkt? Es scheint, als würden die Oger einen Angriff auf unsere Verbündeten planen.\n\nLindie hat so etwas geahnt und uns einige Bomben gegeben, um Belagerungswaffen zu zerstören.\n\nSchüttelt sie nur nicht zu sehr.", sourceObjective = "Jagt 4 Katapulte in der Finsterbrecherzitadelle in die Luft.", progress = "Keine Sorge wegen der Bomben. Die jagen diese Katapulte problemlos hoch.", completion = "Großartig gemacht! Ich muss Lindie ausrichten, dass seine Bomben fabelhaft funktioniert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55990] = { id = 55990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle über ihre Steine", description = "Kapitänin Kelra wird nicht mehr lange durchhalten. Wir müssen die Wärtersteine beschaffen, um das Ritual zu unterbrechen, bevor es sie tötet.\n\nIch werde weiter das Hauptritual schwächen. Nehmt den Ogerhauptleuten in der Nähe die Wärtersteine ab.", sourceObjective = "Beschafft die Wärtersteine von Jugnug, Wug und Grunk und benutzt sie, um Kapitänin Kelra zu befreien.", progress = "Das waren also die Steine, mit denen ich gebunden wurde? Die Oger waren offensichtlich in Sorge, dass Ihr ihre Pläne vereiteln würdet.", completion = "Danke, dass Ihr mich gerettet habt, aber wir haben keine Zeit zu verlieren. Die Oger werden weiterhin versuchen, den Drachen zu erwecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[55991] = { id = 55991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende vom Anfang", description = "Ihr habt gute Arbeit auf der Insel des Verbannten geleistet, <Rekrut/Rekrutin>. Ihr solltet zu den Dracheninseln weiterziehen.\n\nIch fürchte, ich muss meine Pläne ändern und nach Sturmwind zurückkehren. Ich muss herausfinden, wie die Oger an solch mächtige Schattenmagie gelangt sind.\n\nIch bin sicher, wir werden uns wiedersehen. Euch erwarten viele Abenteuer, das weiß ich.", sourceObjective = "Sprecht mit Kalecgos, um zu den Dracheninseln zu reisen.", completion = "Es ist gut, wieder in Sturmwind zu sein.\n\nIch muss unserem König vom Erfolg unserer Mission berichten. Aber ich habe eine Idee, was Ihr bis dahin tun könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[55992] = { id = 55992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungeon: Finsterbrecherzitadelle", description = "Ihr habt Gor'groths Bemühungen verlangsamt, Kalecgos auf der Zitadelle zu kontrollieren, aber das Ritual selbst muss vereitelt werden.\n\nIhr müsst die Zitadelle stürmen und ihn davon abhalten, das Ritual zu vollenden. Seine dunkle Magie ist eine Beleidigung für das Licht.\n\nWir brauchen so viel Hilfe wie möglich. Gor'groths mächtigste Hauptleute erwarten uns in der Zitadelle.", sourceObjective = "Schließt den Dungeon \"Finsterbrecherzitadelle\" ab.", progress = "Ihr müsst Gor'groth töten, bevor es zu spät ist!", completion = "Anscheinend hat sich das Blatt endlich zu unseren Gunsten gewendet. Es ist an der Zeit, wieder nach Sturmwind zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55993] = { id = 55993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein scharfer Vorsprung", description = "In der tiefsten Höhle. Unter der Stadt der Naga. Dort werdet Ihr sie finden.\n\nUnheimliche, kleine Krabben mit scharfen, spitzen Stacheln.\n\nIch glaube, wir können eine Möglichkeit finden, sie zu nutzen. Geschosse funktionieren nicht so gut im Wasser, aber jetzt...\n\nSammelt einige für uns!\n\nSeid vorsichtig, einige sind viel gerissener, als sie sein dürften.", sourceObjective = "Sammelt 12 Zitterstacheln.", progress = "Habt Ihr die Stacheln schon gesammelt?", completion = "Autsch! Die sollten ausreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55994] = { id = 55994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht zum Verzehr geeignet", description = "Die Troggs beobachten alles, was wir tun.\n\nSie sehen, dass wir Öl in die verschiedenen Maschinen gießen, also stehlen sie das Öl jetzt und trinken es. Ich glaube, sie denken, dass es sie in Maschinen verwandeln wird!\n\nWir brauchen das Öl zurück, bevor sie alles auftrinken!", sourceObjective = "Bergt 12 Behälter mit gestohlenem Öl.", progress = "Holt das Öl zurück, schnell!", completion = "Ihr habt gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55995] = { id = 55995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir bekommen das hin", description = "<Die Bohrmaschine macht den Eindruck, als ob sie die Trümmer in der Nähe durchdringen könnte, aber sie ist ganz offensichtlich kaputt.\n\nWenn Ihr die benötigten Ersatzteile einsammelt, sollte Prinz Erazmin Euch zeigen können, wie man sie repariert.>", sourceObjective = "Sammelt 40 Ersatzteile und 1 Energiezelle von Gegnern im Schrottwattdepot.", progress = "Wir Mechagnome bauen immer irgendetwas. Mechagon ist übersät mit halb kaputten oder halb fertigen Konstruktionsprojekten.", completion = "Erscheinen Euch diese kleinen Teile unbedeutend?\n\nBenutzt Eure Fantasie. Findet ihren Zweck. Gebt ihnen Wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[55997] = { id = 55997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Hydras" }
quests[56000] = { id = 56000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krosse Krabben!", description = "{name}, Ihr kommt gerade rechtzeitig. Alles ist bereit für die Krabbenjagd!\n\nAlso gut... Ich weiß, was Ihr denkt. Ein Gründungsmitglied von D.E.H.T.A., das eine Jagd duldet?\n\nIch werde offen zu Euch sein, {name}. Ich habe einen Tresen voll mit hungrigen Murlocs, die nur drei Dinge fressen: Krabben, Fische und Leute.\n\nUnd wenn das nicht Grund genug ist: Wir haben eine Krabbenüberbevölkerung hier in der Gegend, und sie dezimieren die hiesige Käferlarvenpopulation!\n\nWie viele unschuldige Käferlarven müssen noch sterben, bevor wir etwas unternehmen, {name}?", sourceObjective = "Sammelt 12 Knisterscherenkrabben.", progress = "Wie viele unschuldige Käferlarven müssen noch sterben, bevor wir etwas unternehmen, {name}?", completion = "Das sind ja angenehme Scherereien, die Ihr mir da mitbringt.{name}. Gut gemacht! Bitte stellt die Kiste hinter den Tresen und ich kümmere mich um den Rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[56001] = { id = 56001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Bier nix los", description = "Diese nichtsnutzigen Blutflossen sind mit dem ganzen Bier abgehauen!\n\nIch habe mit verschiedenen Brauarten experimentiert, bei denen nur Zutaten aus Nazjatar verwendet werden, aber das ist noch nicht ausgereift. Vorläufig muss ich mich damit zufriedengeben, was ich aus dem Schiffswrack bergen kann.\n\nMeine Biervorräte waren schon begrenzt, aber jetzt ist dank dieser diebischen Blutflossenmurlocs alles weg! Wir werden hier ein paar ziemlich erboste Kunden haben, wenn wir das Bier nicht zurückbekommen.\n\nBitte holt das gestohlene Lagerbier aus dem Blutflossendorf zurück, bevor es zu spät ist!", sourceObjective = "Sammelt 12 Lagerbier mit \"Ozeanhauch\".", progress = "Diese nichtsnutzigen Blutflossen sind mit dem ganzen Bier abgehauen!", completion = "Gute Arbeit, {name}! Ihr habt fast das gesamte gestohlene Bier zurückgeholt. Diese Blutflossen machen mehr Ärger, als uns lieb sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[56002] = { id = 56002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mgglurkys Mugglrgl", description = "Mein Koch Mgglurky hat sein Mugglrgl verloren und weigert sich, zu arbeiten, ehe er es nicht zurückbekommt.\n\nIch habe einen Laden voll mit hungrigen Murlocs und solange Mgglurky nicht kocht, habe ich nichts, um sie zu beköstigen. Wenn Mgglurky nicht bald sein Mugglrgl findet, haben wir hier einen Aufstand am Hals!\n\nIch weiß ja nicht, wie es Euch geht, aber ich habe keine Lust, heute Abend das Hauptgericht zu sein.\n\nHier haben vorhin einige Blutflossen herumgelungert. Durchsucht das Blutflossendorf nach dem Mugglrgl und bringt es mir, wenn Ihr es gefunden habt.", sourceObjective = "Holt Mgglurkys Mugglrgl aus dem Blutflossendorf zurück.", progress = "Wenn Mgglurky nicht bald sein Mugglrgl findet, haben wir hier einen Aufstand am Hals!", completion = "Ihr habt es gefunden! Also das ist ein Mugglrgl? Aus irgendeinem Grund dachte ich, es wäre größer. Mgglurky wird sehr glücklich sein, dass Ihr es zurückgebracht habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[56003] = { id = 56003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenverriegelte Truhe" }
