quests[56030] = { id = 56030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehl des Kriegshäuptlings", description = "Champion, die Dunkle Fürstin erwartet Euch. Es ist Zeit, ihren Plan in die Tat umzusetzen.\n\nUnsere Kriegsschiffe stehen bereit. Der Schlüssel für den Sieg über die Allianz ist zum Greifen nah.\n\nTrefft mich in Zuldazar an Bord der Klagelied. Das, was wir tun werden... tun wir für die Horde.", sourceObjective = "Trefft Euch mit Nathanos Pestrufer auf der Klagelied.", completion = "Ah, das letzte Mitglied unserer Besatzung ist eingetroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[56031] = { id = 56031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Offensive des Wolfs", description = "Champion, Spionagemeister Shaw berichtet, dass die Überreste der Hordenflotte sich zum Ablegen bereit macht.\n\nSie werden für unsere überlegenen Streitkräfte leichte Beute sein. Ergreifen wir diese Gelegenheit, um die von ihnen ausgehende Bedrohung ein für alle Mal auszulöschen!\n\nEs werden bereits Vorbereitungen getroffen, die Segel zu setzen. Kommt schnellstmöglich zum Hafen von Boralus und trefft mich an Bord der Erlösenden Winde!", sourceObjective = "Trefft Euch mit Genn Graumähne an Bord der Erlösenden Winde.", completion = "Ihr kommt gerade rechtzeitig, {name}. \nSpionagemeister Shaw hat mich gerade darüber informiert, was wir in letzter Zeit über die Hordenflotte erfahren haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[56032] = { id = 56032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dreckige Dutzend" }
